/* ==========================================================
   选择 / 填空形态题库 · 对标真题卷面结构
   为什么必须有这一层：
     西城期末卷三年结构完全一致——
       选择 8 题 × 2 分 = 16 分（第 1–8 题）
       填空 8 题 × 2 分 = 16 分（第 9–16 题）
       解答 8 题 = 68 分（第 17–24 题）+ 选做 2 题 10 分
     选择+填空合计 32 分，占卷面近三分之一。
     但站内原有题目全部是「解答题」形态，32 分卷面没有任何对应训练。
     这一层专补这个缺口。
   形态约定（引擎已支持，见 assets/step-engine.js）：
     kind: 'choice' + options: [...] + steps[0].key  → 渲染成 ABCD 按钮
     kind: 'fill'   + steps[0].accept: [...]          → 渲染成输入框
   两者都只有「一步」，因为真题选择/填空本身就是单点判定，
   不是多步推理——多步推理是解答题的事。
   考点选取依据：三年真题选择/填空逐题统计（见每题的 topic 注释）。
   高频考点（3 次）多出几道，低频（1 次）各一道，保证覆盖面与权重一致。
   ========================================================== */
export const SLOT_FORMAT_QUESTIONS = [
  {"id":"cf-ch-01","chapter":"ch-op","calcType":"power","method":null,"tier":"l1","kind":"choice","score":2,"tierName":"选择 · 科学记数法（真题第 2 题，3/3 年）","errorTags":["concept"],"stem":"我国可再生能源年消费量达到 $1100000000$ 吨标煤。将 $1100000000$ 用科学记数法表示应为（　）","options":["$1.1\\times10^{8}$","$1.1\\times10^{9}$","$11\\times10^{8}$","$0.11\\times10^{10}$"],"steps":[{"label":"定 $a$ 与 $n$","ask":"$1100000000$ 写成 $a\\times10^{n}$，其中 $1\\le|a|<10$。","type":"choice","options":["$1.1\\times10^{8}$","$1.1\\times10^{9}$","$11\\times10^{8}$","$0.11\\times10^{10}$"],"key":1,"score":2,"hint":"数一下小数点要向左移几位：$1100000000$ 共 10 位整数，$a$ 取 $1.1$，则 $n=9$。","why":"$1.1\\times10^{9}$。判断标准：$a$ 必须在 $[1,10)$ 内。$11$ 和 $0.11$ 都不满足，直接排除。"}],"solution":"$1100000000=1.1\\times10^{9}$。\n\n【判据】科学记数法要求 $1\\le|a|<10$。选项里 $11\\times10^{8}$ 的系数是 11、$0.11\\times10^{10}$ 的系数是 0.11，都不在区间内，可以不算就排除。\n【数位法】整数位数减 1 就是 $n$：$1100000000$ 是 10 位数，故 $n=9$。"},
  {"id":"cf-ch-02","chapter":"ch-op","calcType":"power","method":null,"tier":"l1","kind":"choice","score":2,"tierName":"选择 · 科学记数法（小数）","errorTags":["concept"],"stem":"某种花粉的直径约为 $0.000035$ 米。将 $0.000035$ 用科学记数法表示应为（　）","options":["$3.5\\times10^{-6}$","$35\\times10^{-6}$","$3.5\\times10^{-5}$","$0.35\\times10^{-4}$"],"steps":[{"label":"定 $n$ 为负","ask":"小于 1 的正数，$n$ 是负数。$0.000035$ 中小数点要向右移几位到 $3.5$？","type":"choice","options":["$3.5\\times10^{-6}$","$35\\times10^{-6}$","$3.5\\times10^{-5}$","$0.35\\times10^{-4}$"],"key":2,"score":2,"hint":"$0.000035\\to3.5$，小数点右移 5 位，故 $n=-5$。","why":"$3.5\\times10^{-5}$。小数情形：原数第一个非零数字前有几个 0（含小数点前那个），$n$ 就是负几。"}],"solution":"$0.000035=3.5\\times10^{-5}$。\n\n【口诀】小数点右移到「$a$ 在 $[1,10)$」为止，移几位 $n$ 就是负几。这里移 5 位，故 $n=-5$。"},
  {"id":"cf-ch-03","chapter":"ch-rational","method":"m-abs-value","tier":"l2","kind":"choice","score":2,"tierName":"选择 · 数轴判断符号（真题第 3/4 题，3/3 年）","errorTags":["concept","sign"],"stem":"有理数 $a$、$b$ 在数轴上的位置如图所示：$a$ 在原点左侧且离原点较远，$b$ 在原点右侧且离原点较近。则下列结论正确的是（　）","fig":{"viewBox":[0,0,220,60],"alt":"数轴上 a 在原点左侧较远，b 在原点右侧较近","elems":[{"t":"seg","a":[15,38],"b":[205,38]},{"t":"pt","at":[110,38],"label":"0","pos":"b"},{"t":"pt","at":[45,38],"label":"a","pos":"b"},{"t":"pt","at":[150,38],"label":"b","pos":"b"}]},"options":["$a+b>0$","$ab<0$ 且 $|a|<|b|$","$a-b>0$","$a+b<0$"],"steps":[{"label":"读位置定符号","ask":"$a<0$、$b>0$，且 $|a|>|b|$。下列结论正确的是？","type":"choice","options":["$a+b>0$","$ab<0$ 且 $|a|<|b|$","$a-b>0$","$a+b<0$"],"key":3,"score":2,"hint":"异号相加取绝对值大的那个的符号。$|a|>|b|$，所以取 $a$ 的符号（负）。","why":"$a+b<0$。异号两数相加，取绝对值较大者的符号。因 $|a|>|b|$，结果为负。"}],"solution":"由图：$a<0$，$b>0$，且 $a$ 离原点更远，即 $|a|>|b|$。\n异号相加，取绝对值大的符号 → $a+b<0$。\n\n【逐项排除】\n· $a+b>0$ 错（应为负）\n· $ab<0$ 对（异号相乘得负），但 $|a|<|b|$ 错（应为 $|a|>|b|$）\n· $a-b=a+(-b)$：$a<0$、$-b<0$，同号相加为负，故 $a-b>0$ 错"},
  {"id":"cf-ch-04","chapter":"ch-rational","method":null,"tier":"l2","kind":"choice","score":2,"tierName":"选择 · 数轴上的距离与中点","errorTags":["concept"],"stem":"数轴上点 $A$ 表示 $-3$，点 $B$ 表示 $5$。若点 $C$ 是线段 $AB$ 的中点，则点 $C$ 表示的数是（　）","options":["$1$","$2$","$4$","$-1$"],"steps":[{"label":"中点公式","ask":"中点坐标 $=\\dfrac{a+b}{2}$。代入 $-3$ 与 $5$。","type":"choice","options":["$1$","$2$","$4$","$-1$"],"key":0,"score":2,"hint":"$\\dfrac{-3+5}{2}=\\dfrac{2}{2}$。","why":"$C$ 表示 $1$。注意不是「$5-(-3)=8$ 再取一半」——那是距离的一半，不是中点坐标。"}],"solution":"中点坐标 $=\\dfrac{-3+5}{2}=1$。\n\n【易错】$AB=|5-(-3)|=8$，一半是 $4$——但 $4$ 是「距离的一半」，不是中点坐标。中点要从 $A$ 向右移 4 个单位：$-3+4=1$，一致。若直接答 4 就错了。"},
  {"id":"cf-ch-05","chapter":"ch-poly","calcType":"bracket","method":"m-like-terms","tier":"l1","kind":"choice","score":2,"tierName":"选择 · 合并同类项辨析（真题第 5 题，3/3 年）","errorTags":["concept","calc"],"stem":"下列计算中正确的是（　）","options":["$2x+3y=5xy$","$6x^{2}-(-x^{2})=5x^{2}$","$-7ab^{2}+4ab^{2}=-3ab^{2}$","$4mn-3mn=1$"],"steps":[{"label":"逐项判断","ask":"哪一项的字母部分完全相同、可以合并？","type":"choice","options":["$2x+3y=5xy$","$6x^{2}-(-x^{2})=5x^{2}$","$-7ab^{2}+4ab^{2}=-3ab^{2}$","$4mn-3mn=1$"],"key":2,"score":2,"hint":"$2x$ 与 $3y$ 字母不同不能合并；$4mn-3mn=mn$ 不是 1；$6x^2-(-x^2)=7x^2$ 不是 $5x^2$。","why":"$-7ab^{2}+4ab^{2}=(-7+4)ab^{2}=-3ab^{2}$，正确。其余三项：字母不同不能合并、系数算错、系数为 1 时漏写字母。"}],"solution":"正确项：$-7ab^{2}+4ab^{2}=(-7+4)ab^{2}=-3ab^{2}$。\n\n【三个错项分别考什么】\n· $2x+3y=5xy$：字母不同，不是同类项，根本不能合并（最高频错误）\n· $6x^{2}-(-x^{2})=5x^{2}$：减去负的等于加上正的，应为 $7x^{2}$\n· $4mn-3mn=1$：系数 $1$ 时字母部分不能丢，应为 $mn$"},
  {"id":"cf-ch-06","chapter":"ch-poly","calcType":"bracket","method":"m-like-terms","tier":"l1","kind":"choice","score":2,"tierName":"选择 · 同类项求参数","errorTags":["concept"],"stem":"若单项式 $2x^{m}y^{3}$ 与 $-3x^{2}y^{n}$ 是同类项，则 $m+n$ 的值为（　）","options":["$3$","$2$","$6$","$5$"],"steps":[{"label":"同类项条件","ask":"同类项要求相同字母的指数分别相等：$x$ 的指数 $m$ 对 $2$，$y$ 的指数 $3$ 对 $n$。则 $m+n=$？","type":"choice","options":["$3$","$2$","$6$","$5$"],"key":3,"score":2,"hint":"先由 $m=2$、$n=3$ 求出，再相加。","why":"$m=2$，$n=3$，故 $m+n=5$。"}],"solution":"同类项：相同字母的指数分别相同。\n$x$ 的指数：$m=2$；$y$ 的指数：$3=n$。\n故 $m+n=2+3=5$。"},
  {"id":"cf-ch-07","chapter":"ch-rational","calcType":"power","method":"m-abs-value","tier":"l1","kind":"choice","score":2,"tierName":"选择 · 绝对值（真题第 1 题，2/3 年）","errorTags":["concept"],"stem":"$-\\dfrac{3}{4}$ 的绝对值是（　）","options":["$-\\dfrac{3}{4}$","$\\dfrac{3}{4}$","$\\dfrac{4}{3}$","$-\\dfrac{4}{3}$"],"steps":[{"label":"绝对值定义","ask":"负数的绝对值等于它的什么？","type":"choice","options":["$-\\dfrac{3}{4}$","$\\dfrac{3}{4}$","$\\dfrac{4}{3}$","$-\\dfrac{4}{3}$"],"key":1,"score":2,"hint":"负数的绝对值是它的相反数，结果一定非负。","why":"$\\left|-\\dfrac34\\right|=\\dfrac34$。绝对值不可能为负，B、D 直接排除。"}],"solution":"$\\left|-\\dfrac{3}{4}\\right|=\\dfrac{3}{4}$。\n\n【秒杀】绝对值一定 $\\ge0$，含负号的选项直接排除；$\\dfrac43$ 是倒数不是绝对值。"},
  {"id":"cf-ch-08","chapter":"ch-rational","method":"m-abs-value","tier":"l2","kind":"choice","score":2,"tierName":"选择 · 相反数与绝对值辨析","errorTags":["concept"],"stem":"下列说法正确的是（　）","options":["相反数等于它本身的数只有 $0$","$-a$ 一定是负数","若 $|a|=|b|$，则 $a=b$","绝对值等于它本身的数只有 $0$"],"steps":[{"label":"逐项验边界","ask":"哪一项在任何情况下都成立？","type":"choice","options":["相反数等于它本身的数只有 $0$","$-a$ 一定是负数","若 $|a|=|b|$，则 $a=b$","绝对值等于它本身的数只有 $0$"],"key":0,"score":2,"hint":"试 $a=-2$：$-a=2$ 是正数，A 错。试 $a=2,b=-2$：$|a|=|b|$ 但 $a\\ne b$，C 错。试 $a=5$：$|5|=5$，D 错。","why":"B 正确：设 $a=-a$，则 $2a=0$，$a=0$。其余三项都能举出反例。"}],"solution":"B 正确。\n\n【逐项反例】\n· A：$a=-2$ 时 $-a=2>0$，不是负数\n· C：$a=2,b=-2$ 时 $|a|=|b|$ 但 $a\\ne b$\n· D：$a=5$ 时 $|5|=5$，非负数都满足，不止 0\n\n【要点】这类题的标准做法是「逐项找反例」，找到就排除，不要试图证明。"},
  {"id":"cf-ch-09","chapter":"ch-geo","method":"m-unfold","tier":"l2","kind":"choice","score":2,"tierName":"选择 · 展开图识别（真题第 3/4 题，2/3 年）","errorTags":["concept"],"stem":"下列图形中，可以作为一个长方体（正方体）的展开图的是（　）","options":["「田」字形（2×2 四个正方形）","「一」字形排列的六个正方形","「凹」字形","「十」字形（中间一个、四边各一个、再加一个）"],"steps":[{"label":"排除不能折的","ask":"哪种形状可以折成正方体？","type":"choice","options":["「田」字形（2×2 四个正方形）","「一」字形排列的六个正方形","「凹」字形","「十」字形（中间一个、四边各一个、再加一个）"],"key":3,"score":2,"hint":"「田」字形四格共用一个顶点，折叠时两个面会撞在一起。","why":"「田」字形（2×2）折叠时必有两个面重叠，不能围成正方体。正方体展开图共 11 种，含「一四一」「二三一」「二二二」「三三」型，没有「田」字型。"}],"solution":"能折成正方体的是「十」字形（属「一四一」型变体）。\n\n【判据】正方体展开图共 11 种，可按行数记：\n· 一四一型（6 种）· 二三一型（3 种）· 二二二型（1 种）· 三三型（1 种）\n「田」字形（2×2）一定不能折——四个面共用一个顶点，折叠必重叠。\n\n【应试技巧】看到「田」「凹」直接排除。"},
  {"id":"cf-ch-10","chapter":"ch-eq","method":"m-angle-calc","tier":"l2","kind":"choice","score":2,"tierName":"选择 · 补角列方程（真题第 6 题，2/3 年）","errorTags":["method"],"stem":"已知一个角比它的补角小 $30°$，则这个角的大小为（　）","options":["$60°$","$105°$","$75°$","$30°$"],"steps":[{"label":"设元列方程","ask":"设这个角为 $x$，补角为 $180°-x$。「这个角比它的补角小 $30°$」，解得这个角是？","type":"choice","options":["$60°$","$105°$","$75°$","$30°$"],"key":2,"score":2,"hint":"「$x$ 比补角小」→ $x$ 更小 → $x=$ 补角 $-30°$。","why":"$x=180°-x-30°$，即 $2x=150°$，$x=75°$。"}],"solution":"设这个角为 $x$，补角为 $180°-x$。\n「这个角比它的补角小 $30°$」→ $x=(180°-x)-30°$。\n$2x=150°$，$x=75°$。\n\n【验证】补角 $=105°$，$105°-75°=30°$ ✓\n【易错】把「小」读成「大」，列出 $x=(180°-x)+30°$，会得到 $105°$——那是补角，不是所求角。"},
  {"id":"cf-ch-11","chapter":"ch-eq","method":"m-angle-calc","tier":"l2","kind":"choice","score":2,"tierName":"选择 · 余角与补角的关系","errorTags":["method","concept"],"stem":"一个角的补角是它的余角的 $4$ 倍，则这个角为（　）","options":["$60°$","$45°$","$30°$","$75°$"],"steps":[{"label":"列方程","ask":"设角为 $x$，补角是余角的 $4$ 倍。解方程后这个角是？","type":"choice","options":["$60°$","$45°$","$30°$","$75°$"],"key":0,"score":2,"hint":"「补角是余角的 4 倍」→ 补角 $=4\\times$ 余角。","why":"$180°-x=4(90°-x)$ → $180°-x=360°-4x$ → $3x=180°$ → $x=60°$。"}],"solution":"设这个角为 $x$。补角 $180°-x$，余角 $90°-x$。\n$180°-x=4(90°-x)$\n$180°-x=360°-4x$\n$3x=180°$\n$x=60°$\n\n【验证】补角 $120°$，余角 $30°$，$120=4\\times30$ ✓\n【易错】余角补角写反，会得到无解或负数——验算能立刻发现。"},
  {"id":"cf-ch-12","chapter":"ch-geo","method":null,"tier":"l2","kind":"choice","score":2,"tierName":"选择 · 三视图（真题第 8 题，1/3 年）","errorTags":["concept"],"stem":"一个圆柱竖直放置（底面朝下），从正面看得到的图形是（　）","options":["圆","长方形","三角形","梯形"],"steps":[{"label":"正面看到什么","ask":"竖直放置的圆柱，从**正面**看得到的图形是？","type":"choice","options":["圆","长方形","三角形","梯形"],"key":1,"score":2,"hint":"侧面看是长方形（柱身），俯视看是底面（圆）。","why":"正面看到柱身轮廓 → 长方形；上面看到底面 → 圆。"}],"solution":"正面看：长方形（柱身的侧面投影）。\n上面看：圆（底面）。\n\n【要点】三视图按「正面 / 上面 / 左面」三个方向投影。竖直圆柱的正面与左面都是长方形，上面是圆。"},
  {"id":"cf-ch-13","chapter":"ch-expr","method":null,"tier":"l2","kind":"choice","score":2,"tierName":"选择 · 反比例关系判断（真题 2024-25 第 7 题）","errorTags":["concept"],"stem":"下列问题中的两个量成反比例关系的是（　）","options":["每天阅读半小时，总时长与天数","圆柱底面积一定，体积与高","长方形周长一定，相邻两边长","路程一定，速度与时间"],"steps":[{"label":"判乘积是否一定","ask":"反比例的本质是「两个量的乘积一定」。下列哪一对量成反比例关系？","type":"choice","options":["每天阅读半小时，总时长与天数","圆柱底面积一定，体积与高","长方形周长一定，相邻两边长","路程一定，速度与时间"],"key":3,"score":2,"hint":"乘积一定→反比例；比值一定→正比例。","why":"速度×时间=路程（定值），乘积一定，成反比例。其余：总时长÷天数=0.5 是比值一定（正比例）；体积÷高=底面积（正比例）。"}],"solution":"反比例：两个量的**乘积**一定（$xy=k$）。\n正比例：两个量的**比值**一定（$y=kx$）。\n\n逐项：\n· 速度×时间=路程（定）→ 乘积一定 → **反比例** ✓\n· 总时长÷天数=0.5（定）→ 比值一定 → 正比例\n· 体积÷高=底面积（定）→ 比值一定 → 正比例\n· 周长一定时，相邻两边之和一定（和一定），既不正也不反\n\n【要点】先问「乘积一定还是比值一定」，再判断。"},
  {"id":"cf-ch-14","chapter":"ch-op","method":"m-newdef","tier":"l3","kind":"choice","score":2,"tierName":"选择 · 新定义运算多结论（真题第 8 题）","errorTags":["method"],"stem":"对任意两个有理数 $a$、$b$，定义运算 $a\\oplus b=|a+b|-|a-b|$。有下列四个结论：\n① $3\\oplus(-2)=-4$；\n② $a\\oplus b=b\\oplus a$；\n③ $a\\oplus a=0$；\n④ 若 $a\\oplus b=0$，则 $a=b$。\n其中所有正确结论的序号是（　）","options":["①②","①②③","①③","②③④"],"steps":[{"label":"逐条验算","ask":"① $3\\oplus(-2)=|1|-|5|=-4$ ✓；② 交换后绝对值内两项互换，结果不变 ✓；③ $a\\oplus a=|2a|=2|a|$，$a=1$ 时为 $2$ ✗；④ $a\\oplus b=0$ 只需 $a=0$ 或 $b=0$ ✗。正确的是？","type":"choice","options":["①②","①②③","①③","②③④"],"key":0,"score":2,"hint":"③ 代 $a=1$ 得 2 不为 0；④ 代 $a=0,b=5$ 得 0 但 $a\\ne b$。","why":"①② 正确。③ 错（$a\\oplus a=2|a|$，仅 $a=0$ 为 0）；④ 错（$a=0$ 或 $b=0$ 即可，不必 $a=b$）。"}],"solution":"① $3\\oplus(-2)=|1|-|5|=1-5=-4$ ✓\n② $b\\oplus a=|a+b|-|b-a|=a\\oplus b$ ✓\n③ $a\\oplus a=2|a|$，$a\\ne0$ 时不为 $0$ ✗\n④ $a\\oplus b=0\\iff ab=0\\iff a=0$ 或 $b=0$，不必 $a=b$ ✗\n\n正确：①②。\n\n【要点】多结论题优先用「特殊值反例」排除。"},
  {"id":"cf-ch-15","chapter":"ch-poly","calcType":"simplify","method":"m-like-terms","tier":"l2","kind":"choice","score":2,"tierName":"选择 · 整式加减（图形边长）","errorTags":["calc"],"stem":"一个长方形的长为 $2a+b$，宽为 $a-b$，则它的周长为（　）","options":["$3a$","$6a+2b$","$6a$","$3a+b$"],"steps":[{"label":"先求长加宽再乘2","ask":"长 $+$ 宽 $=(2a+b)+(a-b)=3a$；周长 $=2\\times3a=$？","type":"choice","options":["$3a$","$6a+2b$","$6a$","$3a+b$"],"key":2,"score":2,"hint":"$(2a+b)+(a-b)=3a$，$b$ 与 $-b$ 抵消；再乘 $2$。","why":"周长 $=2\\times3a=6a$。$3a$ 是漏乘 2，$6a+2b$ 是没抵消 $b$。"}],"solution":"长 $+$ 宽 $=(2a+b)+(a-b)=3a$。\n周长 $=2\\times3a=6a$。\n\n【易错】直接答 $3a$（漏乘 2）；答 $6a+2b$（把 $b$ 当成没抵消）。"},
  {"id":"cf-ch-16","chapter":"ch-expr","method":"m-substitute","tier":"l2","kind":"choice","score":2,"tierName":"选择 · 整体代入求值（真题第 7 题）","errorTags":["method"],"stem":"若 $x-3y=-4$，则 $(x-3y)^{2}+2x-6y-10$ 的值为（　）","options":["$14$","$-2$","$2$","$-18$"],"steps":[{"label":"整体代换","ask":"$2x-6y=2(x-3y)$。把 $x-3y=-4$ 整体代入，原式等于？","type":"choice","options":["$14$","$-2$","$2$","$-18$"],"key":1,"score":2,"hint":"$(-4)^2=16$，$2\\times(-4)=-8$，故 $16-8-10$。","why":"$16-8-10=-2$。故答案为 $-2$。"}],"solution":"原式 $=(x-3y)^{2}+2(x-3y)-10$。\n把 $x-3y=-4$ 整体代入：\n$(-4)^{2}+2\\times(-4)-10=16-8-10=-2$。\n\n【答案】$-2$。\n【要点】看到 $2x-6y$ 要立刻想到提公因数 $2$，变成 $2(x-3y)$——这是「整体代入」的识别信号。"},
  {"id":"cf-ch-17","chapter":"ch-expr","method":"m-pattern","tier":"l3","kind":"choice","score":2,"tierName":"选择 · 图形规律（真题第 8 题）","errorTags":["method"],"stem":"用边长相等的正方形和等边三角形卡片按规律拼图：第 1 个图形共 $7$ 枚，第 2 个共 $12$ 枚，第 3 个共 $17$ 枚……按此规律，第 $n$ 个图形所用卡片总数为（　）","options":["$5n+7$","$6n+1$","$5n-2$","$5n+2$"],"steps":[{"label":"找公差定通项","ask":"数列 $7,12,17$ 公差 $5$、首项 $7$。通项 $a_n=7+5(n-1)$ 化简为？","type":"choice","options":["$5n+7$","$6n+1$","$5n-2$","$5n+2$"],"key":3,"score":2,"hint":"$7+5n-5$。","why":"$a_n=5n+2$。验证 $n=2\\to12$ ✓，$n=3\\to17$ ✓。"}],"solution":"公差 $d=5$，首项 $7$。\n$a_n=7+5(n-1)=5n+2$。\n\n【验证】$n=1\\to7$ ✓，$n=2\\to12$ ✓，$n=3\\to17$ ✓\n【易错】写 $5n+7$（把首项当截距）。"},
  {"id":"cf-ch-18","chapter":"ch-rational","calcType":"power","method":null,"tier":"l1","kind":"choice","score":2,"tierName":"选择 · 相反数（真题第 1 题）","errorTags":["concept"],"stem":"$-\\dfrac{3}{4}$ 的相反数是（　）","options":["$-\\dfrac{3}{4}$","$\\dfrac{4}{3}$","$\\dfrac{3}{4}$","$-\\dfrac{4}{3}$"],"steps":[{"label":"相反数定义","ask":"相反数只需改变符号，数值部分不变。","type":"choice","options":["$-\\dfrac{3}{4}$","$\\dfrac{4}{3}$","$\\dfrac{3}{4}$","$-\\dfrac{4}{3}$"],"key":2,"score":2,"hint":"只变符号，不取倒数。","why":"$-\\dfrac34$ 的相反数是 $\\dfrac34$。$\\dfrac43$ 是倒数，不是相反数。"}],"solution":"$-\\dfrac{3}{4}$ 的相反数是 $\\dfrac{3}{4}$。\n\n【区分三个概念】\n· 相反数：只变符号（$-\\frac34\\to\\frac34$）\n· 倒数：分子分母颠倒（$-\\frac34\\to-\\frac43$）\n· 绝对值：去掉符号（$|-\\frac34|=\\frac34$）\n注意绝对值与相反数在这题答案相同，但概念不同。"},
  {"id":"cf-ch-19","chapter":"ch-geo","method":null,"tier":"l1","kind":"choice","score":2,"tierName":"选择 · 点线面体概念","errorTags":["concept"],"stem":"「点动成线，线动成面，面动成体」。下列现象中，能说明「面动成体」的是（　）","options":["一个长方形绕它的一边旋转一周形成一个圆柱","汽车雨刷在挡风玻璃上划出扇形","流星划过夜空","旋转的门"],"steps":[{"label":"辨「什么动成什么」","ask":"哪个现象能说明「面动成体」？","type":"choice","options":["一个长方形绕它的一边旋转一周形成一个圆柱","汽车雨刷在挡风玻璃上划出扇形","流星划过夜空","旋转的门"],"key":0,"score":2,"hint":"长方形是面，旋转后得到的是立体（圆柱），即体。","why":"长方形（面）绕一边旋转一周 → 圆柱（体），是「面动成体」。雨刷是线动成面，流星是点动成线。"}],"solution":"长方形（面）绕一边旋转一周 → 圆柱（体）：**面动成体** ✓\n\n其余对应：\n· 雨刷划出扇形：线动成面\n· 流星划过夜空：点动成线\n· 旋转的门：面绕轴转动，仍在同一平面附近，不构成体"},
  {"id":"cf-ch-20","chapter":"ch-geo","method":"m-unfold","tier":"l2","kind":"choice","score":2,"tierName":"选择 · 展开图相对面","errorTags":["concept"],"stem":"正方体展开图中，同一行有四个面依次为「前、右、后、左」。则「前」的相对面是（　）","options":["右","后","左","无法确定"],"steps":[{"label":"用「隔一相对」","ask":"「前、右、后、左」同行排列，「前」的相对面是？","type":"choice","options":["右","后","左","无法确定"],"key":1,"score":2,"hint":"「前、右、后、左」中，前与后隔了「右」，右与左隔了「后」。","why":"同一行隔一个面即相对：前与后相对，右与左相对。故「前」的相对面是「后」。"}],"solution":"同一行（列）中，隔一个面的两个面折叠后相对。\n「前、右、后、左」：\n· 前 —（隔 右）— 后 → 前与后相对\n· 右 —（隔 后）— 左 → 右与左相对\n\n故「前」的相对面是「后」。\n\n【口诀】「隔一相对」，同行同列都适用。"},
  {"id":"cf-fi-01","chapter":"ch-op","method":null,"tier":"l1","kind":"fill","score":2,"tierName":"填空 · 四舍五入（真题第 9 题，2/3 年）","errorTags":["concept"],"stem":"用四舍五入法把 $4.0692$ 精确到 $0.01$，所得到的近似数为 ___。","steps":[{"label":"看下一位","ask":"精确到 $0.01$ 即保留两位小数。第三位是 $9$，应进位。结果？","type":"fill","accept":["4.07"],"answer":"4.07","score":2,"hint":"$4.0692$：保留 $4.06$，第三位 $9\\ge5$，进一位 → $4.07$。","why":"$4.07$。"}],"solution":"$4.0692$ 精确到 $0.01$（两位小数）：看第三位 $9$，$9\\ge5$ 故进位，$4.06\\to4.07$。\n\n【易错】精确到 $0.01$ 是保留**两位**小数，不是一位。答案要写成 $4.07$，不是 $4.1$。"},
  {"id":"cf-fi-02","chapter":"ch-op","method":null,"tier":"l1","kind":"fill","score":2,"tierName":"填空 · 近似数与精确度（含万位）","errorTags":["concept"],"stem":"把 $2.997\\times10^{5}$ 精确到万位，所得近似数为 ___。","steps":[{"label":"先还原再看位","ask":"$2.997\\times10^{5}=299700$。精确到万位即保留到「万」，$299700$ 的万位是 $9$（$29$ 万…），下一位是 $9$，进位。结果？","type":"fill","accept":["300000","3.0×10^5","3.0*10^5","$3.0\\times10^{5}$","30万"],"answer":"300000","score":2,"hint":"$299700\\approx300000$（万位 $9$ 进位成 $30$ 万）。","why":"$299700$ 精确到万位 $=300000$，即 $3.0\\times10^{5}$。"}],"solution":"$2.997\\times10^{5}=299700$。\n精确到万位：万位是 $9$（$299700=29$ 万 $9700$），下一位（千位）是 $9\\ge5$，进位 → $30$ 万 $=300000$。\n\n【注意】进位后整数位增加，$299700\\to300000$，写成科学记数法是 $3.0\\times10^{5}$（保留两位有效数字体现精度）。"},
  {"id":"cf-fi-03","chapter":"ch-geo","method":"m-angle-calc","tier":"l1","kind":"fill","score":2,"tierName":"填空 · 度分秒换算（真题第 10 题，2/3 年）","errorTags":["calc"],"stem":"计算：$31°15\\prime\\times4=$ ___ $°$。","steps":[{"label":"先乘分","ask":"$15\\prime\\times4=60\\prime$，而 $60\\prime=1°$。故总度数？","type":"fill","accept":["125","125°"],"answer":"125°","score":2,"hint":"$31°\\times4=124°$，$15\\prime\\times4=60\\prime=1°$，合计 $125°$。","why":"$125°$。"}],"solution":"$31°15\\prime\\times4$：\n度：$31°\\times4=124°$\n分：$15\\prime\\times4=60\\prime=1°$\n合计 $124°+1°=125°$。\n\n【要点】度分秒是 60 进制：$60\\prime=1°$，$60\\prime\\prime=1\\prime$。乘完后必须把满 60 的分进位成度。"},
  {"id":"cf-fi-04","chapter":"ch-geo","method":"m-angle-calc","tier":"l1","kind":"fill","score":2,"tierName":"填空 · 度分秒减法","errorTags":["calc"],"stem":"计算：$90°-37°28\\prime=$ ___ 。","steps":[{"label":"借 1 度","ask":"$90°$ 借 $1°$ 变成 $89°60\\prime$，再减 $37°28\\prime$。结果？","type":"fill","accept":["52°32′","52°32\\prime","52度32分","52°32"],"answer":"52°32′","score":2,"hint":"$89°-37°=52°$，$60\\prime-28\\prime=32\\prime$。","why":"$52°32\\prime$。"}],"solution":"$90°=89°60\\prime$（借 $1°$ 换成 $60\\prime$）。\n$89°60\\prime-37°28\\prime$：\n度：$89°-37°=52°$\n分：$60\\prime-28\\prime=32\\prime$\n结果 $52°32\\prime$。\n\n【要点】度分秒减法不够减时要「借 1 度 = 60 分」，这是必考操作。"},
  {"id":"cf-fi-05","chapter":"ch-eq","method":"m-eq-param","tier":"l2","kind":"fill","score":2,"tierName":"填空 · 方程解求参数（真题第 12/14 题，3/3 年）","errorTags":["concept"],"stem":"若 $x=6$ 是关于 $x$ 的方程 $3x+2m=8$ 的解，则 $m$ 的值为 ___。","steps":[{"label":"代入解","ask":"把 $x=6$ 代入：$3\\times6+2m=8$，即 $18+2m=8$。$m=$？","type":"fill","accept":["-5"],"answer":"-5","score":2,"hint":"$2m=8-18=-10$。","why":"$m=-5$。"}],"solution":"把 $x=6$ 代入 $3x+2m=8$：\n$3\\times6+2m=8$\n$18+2m=8$\n$2m=-10$\n$m=-5$\n\n【要点】「是方程的解」意味着代入后等式成立——这是求参数的标准入口，三年考了三次。"},
  {"id":"cf-fi-06","chapter":"ch-eq","method":"m-eq-param","tier":"l2","kind":"fill","score":2,"tierName":"填空 · 方程解求参数（含分数系数）","errorTags":["concept","calc"],"stem":"若 $x=2$ 是关于 $x$ 的方程 $kx-3=2x+1$ 的解，则 $k$ 的值为 ___。","steps":[{"label":"代入整理","ask":"代入 $x=2$：$2k-3=4+1=5$。$k=$？","type":"fill","accept":["4"],"answer":"4","score":2,"hint":"$2k=5+3=8$。","why":"$k=4$。"}],"solution":"把 $x=2$ 代入 $kx-3=2x+1$：\n$2k-3=2\\times2+1$\n$2k-3=5$\n$2k=8$\n$k=4$\n\n【注意】方程两边都有 $x$，代入时两边都要代。只代左边是常见错误。"},
  {"id":"cf-fi-07","chapter":"ch-poly","method":null,"tier":"l2","kind":"fill","score":2,"tierName":"填空 · 单项式构造（真题第 12 题，2/3 年）","errorTags":["concept"],"stem":"写出一个同时满足以下两个条件的单项式：①系数是负数；②次数是 $5$。这个单项式可以是 ___。","steps":[{"label":"定系数与次数","ask":"系数为负、次数为 5（所有字母指数之和 = 5）。例如 $-2x^{3}y^{2}$ 的系数与次数是？","type":"fill","accept":["-2x^3y^2","-x^5","-3a^2b^3","-x^2y^3","-a^4b","-2x^5"],"answer":"-2x^3y^2（答案不唯一）","score":2,"hint":"系数写个负数，字母指数加起来等于 5 即可。","why":"答案不唯一。如 $-2x^{3}y^{2}$：系数 $-2<0$ ✓，次数 $3+2=5$ ✓。"}],"solution":"答案不唯一。示例：$-2x^{3}y^{2}$\n· 系数 $-2$ 是负数 ✓\n· 次数 $=3+2=5$ ✓\n\n【要点】次数是**所有字母指数之和**，不是单个字母的指数。写 $-2x^{5}$ 也对（次数 5），但写 $-2x^{3}y^{3}$ 就错了（次数 6）。"},
  {"id":"cf-fi-08","chapter":"ch-poly","calcType":"bracket","method":null,"tier":"l2","kind":"fill","score":2,"tierName":"填空 · 单项式系数与次数","errorTags":["concept"],"stem":"单项式 $-\\dfrac{3\\pi x^{2}y}{5}$ 的系数是 ___，次数是 ___。","steps":[{"label":"辨系数","ask":"系数包含数字与 $\\pi$（$\\pi$ 是常数不是字母）。系数是？","type":"fill","accept":["-3π/5","-3\\pi/5","-0.6π"],"answer":"-3π/5","score":1,"hint":"$\\pi$ 是常数，算进系数里。","why":"系数 $=-\\dfrac{3\\pi}{5}$。"},{"label":"数次数","ask":"$x$ 的指数 2 加 $y$ 的指数 1，次数是？","type":"fill","accept":["3"],"answer":"3","score":1,"hint":"$2+1$。","why":"次数 $=3$。"}],"solution":"系数 $=-\\dfrac{3\\pi}{5}$，次数 $=2+1=3$。\n\n【关键】$\\pi$ 是常数，不是字母，所以算进系数里。这是最高频的单项式陷阱。\n【易错】把系数写成 $-\\dfrac35$（漏了 $\\pi$），或把次数算成 5（把 $\\pi$ 当字母）。"},
  {"id":"cf-fi-09","chapter":"ch-expr","method":null,"tier":"l2","kind":"fill","score":2,"tierName":"填空 · 列代数式（真题第 15 题，2/3 年）","errorTags":["express"],"stem":"某商品原价是每件 $a$ 元，第一次降价打「九折」，第二次降价每件又减 $50$ 元，则第二次降价后的售价为每件 ___ 元（用含 $a$ 的式子表示）。","steps":[{"label":"分两次降价","ask":"九折 = 原价 $\\times0.9$，再减 $50$。式子？","type":"fill","accept":["0.9a-50","0.9*a-50","90%a-50","0.9a−50"],"answer":"0.9a-50","score":2,"hint":"先乘 $0.9$ 再减 $50$：$0.9a-50$。","why":"$0.9a-50$。"}],"solution":"第一次降价打九折：$0.9a$ 元。\n第二次每件再减 $50$ 元：$0.9a-50$ 元。\n\n【易错】\n· 写成 $0.9(a-50)$：那是先减后打折，顺序错了\n· 写成 $a-50\\times0.9$：运算顺序错，$50$ 不该打折\n· 写 $0.9a-50$ 时注意「九折」是乘 $0.9$ 不是乘 $9$"},
  {"id":"cf-fi-10","chapter":"ch-expr","method":null,"tier":"l2","kind":"fill","score":2,"tierName":"填空 · 列代数式（连续变化）","errorTags":["express"],"stem":"某商品原价为 $x$ 元，先提价 $20\\%$，再打八折出售，则最终售价为 ___ 元（用含 $x$ 的式子表示）。","steps":[{"label":"逐步乘","ask":"提价 $20\\%$ 是乘 $1.2$；再打八折是乘 $0.8$。式子？","type":"fill","accept":["0.96x","1.2x*0.8","0.8*1.2x","96%x"],"answer":"0.96x","score":2,"hint":"$1.2x\\times0.8=0.96x$。","why":"$0.96x$（比原价低 4%）。"}],"solution":"提价 $20\\%$：$1.2x$。\n再打八折：$1.2x\\times0.8=0.96x$。\n\n【结论】先提 20% 再打八折，最终是原价的 $96\\%$，**比原价还低**。\n【易错】以为「提 20% 再打八折」等于原价——实际是 $1.2\\times0.8=0.96$。这类题考的就是「百分比不能直接相加减」。"},
  {"id":"cf-fi-11","chapter":"ch-geo","method":"m-seg-count","tier":"l2","kind":"fill","score":2,"tierName":"填空 · 线段中点（真题第 13 题，2/3 年）","errorTags":["calc"],"stem":"如图，$C$ 是线段 $AB$ 的中点，点 $D$ 在线段 $CB$ 上，$E$ 是线段 $DB$ 的中点。若 $AB=14$，$EB=2$，则 $CD$ 的长为 ___。","steps":[{"label":"求 CB","ask":"$C$ 是中点，$AB=14$，则 $CB=$？","type":"fill","accept":["7"],"answer":"7","score":1,"hint":"$14\\div2$。","why":"$CB=7$。"},{"label":"求 DB 与 CD","ask":"$E$ 是 $DB$ 中点，$EB=2$，则 $DB=4$。$CD=CB-DB=$？","type":"fill","accept":["3"],"answer":"3","score":1,"hint":"$7-4$。","why":"$CD=7-4=3$。"}],"solution":"$C$ 是 $AB$ 中点 → $CB=\\dfrac12\\times14=7$。\n$E$ 是 $DB$ 中点，$EB=2$ → $DB=2\\times2=4$。\n$D$ 在 $CB$ 上 → $CD=CB-DB=7-4=3$。\n\n【要点】线段计算题按「已知条件逐个推」：中点给一半，再从大段减小段。"},
  {"id":"cf-fi-12","chapter":"ch-geo","method":"m-seg-count","tier":"l2","kind":"fill","score":2,"tierName":"填空 · 线段中点（含分类）","errorTags":["calc","method"],"stem":"线段 $AB=10$，$C$ 为线段 $AB$ 的中点，点 $D$ 在**直线** $AB$ 上，若 $BD=3$，则 $CD=$ ___。","steps":[{"label":"求 CB","ask":"$C$ 是中点，$AB=10$，$CB=$？","type":"fill","accept":["5"],"answer":"5","score":1,"hint":"$10\\div2$。","why":"$CB=5$。"},{"label":"分类讨论","ask":"注意题说「直线 AB」不是「线段」——$D$ 可在 $B$ 的两侧。两种情形下 $CD$ 分别等于？","type":"fill","accept":["2或8","2 或 8","8或2","2,8"],"answer":"2 或 8","score":1,"hint":"$D$ 在 $B$ 左侧：$CD=5-3=2$；$D$ 在 $B$ 右侧：$CD=5+3=8$。","why":"$CD=2$ 或 $CD=8$。这是「点在直线上」的必分类陷阱。"}],"solution":"$C$ 是中点，$CB=5$。\n关键是「点 $D$ 在**直线** $AB$ 上」——$D$ 可以在 $B$ 的左侧或右侧：\n· $D$ 在 $B$ 左侧（在线段 $AB$ 上）：$CD=CB-BD=5-3=2$\n· $D$ 在 $B$ 右侧（在 $AB$ 延长线上）：$CD=CB+BD=5+3=8$\n\n故 $CD=2$ 或 $8$。\n\n【要点】「直线」与「线段」一字之差，决定要不要分类。真题三年有两年考这个陷阱。"},
  {"id":"cf-fi-13","chapter":"ch-rational","method":"m-abs-value","tier":"l2","kind":"fill","score":2,"tierName":"填空 · 绝对值非负性（真题 2022-23 第 11 题）","errorTags":["concept"],"stem":"若 $|x+1|+(y-8)^{2}=0$，则 $x-y$ 的值为 ___。","steps":[{"label":"非负性","ask":"两项都 $\\ge0$，和为 $0$ → 各自为 $0$。故 $x+1=0$、$y-8=0$。$x$、$y$ 分别是？","type":"fill","accept":["x=-1,y=8","-1和8"],"answer":"x=-1, y=8","score":1,"hint":"两个非负数之和为 0，只能都等于 0。","why":"$x=-1$，$y=8$。"},{"label":"求值","ask":"$x-y=-1-8=$？","type":"fill","accept":["-9"],"answer":"-9","score":1,"hint":"$-1-8$。","why":"$-9$。"}],"solution":"$|x+1|\\ge0$，$(y-8)^{2}\\ge0$，两者之和为 $0$ → 各自必须为 $0$。\n$x+1=0\\Rightarrow x=-1$\n$y-8=0\\Rightarrow y=8$\n$x-y=-1-8=-9$。\n\n【要点】「几个非负数之和为 0 → 各自为 0」是非负性的核心应用，三年考了两次。"},
  {"id":"cf-fi-14","chapter":"ch-geo","method":null,"tier":"l1","kind":"fill","score":2,"tierName":"填空 · 点与直线位置关系（真题 2024-25 第 10 题）","errorTags":["express"],"stem":"如图，点 $P$ 不在直线 $l$ 上。用适当的语句表述点 $P$ 与直线 $l$ 的关系：___。","steps":[{"label":"规范表述","ask":"点不在直线上，几何语言怎么说？","type":"fill","accept":["点P在直线l外","点 P 在直线 l 外","点P在直线l外","P在l外"],"answer":"点 P 在直线 l 外","score":2,"hint":"规范说法是「点在直线外」，不是「点不在直线上」。","why":"点 $P$ 在直线 $l$ 外。"}],"solution":"点 $P$ 在直线 $l$ 外。\n\n【几何语言规范】\n· 点在直线上：点 $P$ 在直线 $l$ 上\n· 点不在直线上：点 $P$ 在直线 $l$ **外**\n真题考的是「用规范语句表述」，写「不在直线上」不算规范——这是几何语言的入门考点。"},
  {"id":"cf-fi-15","chapter":"ch-geo","method":"m-angle-calc","tier":"l2","kind":"fill","score":2,"tierName":"填空 · 角的和差（真题 2024-25 第 13 题）","errorTags":["calc"],"stem":"如图，$\\angle AOB=90°$，$\\angle BOC=14°$，$OC$ 在 $\\angle AOB$ 内部。则 $\\angle AOC=$ ___ $°$。","steps":[{"label":"内部则相减","ask":"$OC$ 在内部，$\\angle AOC=\\angle AOB-\\angle BOC$。等于？","type":"fill","accept":["76","76°"],"answer":"76°","score":2,"hint":"$90°-14°$。","why":"$76°$。"}],"solution":"$OC$ 在 $\\angle AOB$ 内部 → $\\angle AOC=\\angle AOB-\\angle BOC=90°-14°=76°$。\n\n【要点】「在内部」是相减的前提。若没说在内部，就要考虑 $OC$ 在外部的情形（相加）。"},
  {"id":"cf-fi-16","chapter":"ch-rational","method":null,"tier":"l2","kind":"fill","score":2,"tierName":"填空 · 数轴判断符号（多结论）","errorTags":["concept"],"stem":"有理数 $a$、$b$ 在数轴上的位置如图：$a$ 在原点左侧且离原点较远，$b$ 在原点右侧且离原点较近。则下列结论中正确的是 ___（填序号）。\n① $ab<0$　② $a+b<0$　③ $a-b>0$　④ $|a|>|b|$","fig":{"viewBox":[0,0,220,60],"alt":"a 在原点左侧较远，b 在原点右侧较近","elems":[{"t":"seg","a":[15,38],"b":[205,38]},{"t":"pt","at":[110,38],"label":"0","pos":"b"},{"t":"pt","at":[45,38],"label":"a","pos":"b"},{"t":"pt","at":[150,38],"label":"b","pos":"b"}]},"steps":[{"label":"逐条判断","ask":"$a<0,b>0,|a|>|b|$。哪几条正确？","type":"fill","accept":["①②④","124","1,2,4","①②④正确"],"answer":"①②④","score":2,"hint":"①异号相乘得负✓ ②异号相加取绝对值大的符号✓ ③$a-b=a+(-b)$，两个负数相加得负✗ ④由图直接读出✓","why":"①②④ 正确。③ 错：$a<0$ 且 $-b<0$，同号相加为负，故 $a-b<0$。"}],"solution":"由图：$a<0$，$b>0$，$|a|>|b|$。\n① $ab$：异号相乘 → 负 → $ab<0$ ✓\n② $a+b$：异号相加取绝对值大者符号 → 负 → $a+b<0$ ✓\n③ $a-b=a+(-b)$：$a<0$、$-b<0$，两个负数相加为负 → $a-b<0$，故 ③ 错\n④ $|a|>|b|$：$a$ 离原点更远 ✓\n\n正确：①②④。\n\n【要点】③ 是最容易错的——减去一个正数等于加上负数，两个负数相加一定为负。"},
  {"id":"cf-fi-17","chapter":"ch-geo","method":"m-angle-calc","tier":"l2","kind":"fill","score":2,"tierName":"填空 · 角平分线与角的和差","errorTags":["calc"],"stem":"已知 $\\angle AOB=120°$，$OC$ 平分 $\\angle AOB$，$OD$ 在 $\\angle BOC$ 内部且 $\\angle BOD=20°$，则 $\\angle COD=$ ___ $°$。","steps":[{"label":"求 BOC","ask":"$OC$ 平分 $\\angle AOB=120°$，$\\angle BOC=$？","type":"fill","accept":["60"],"answer":"60","score":1,"hint":"$120\\div2$。","why":"$60°$。"},{"label":"求 COD","ask":"$OD$ 在 $\\angle BOC$ 内部，$\\angle COD=\\angle BOC-\\angle BOD=$？","type":"fill","accept":["40"],"answer":"40","score":1,"hint":"$60-20$。","why":"$40°$。"}],"solution":"$OC$ 平分 $\\angle AOB$ → $\\angle BOC=\\dfrac12\\times120°=60°$。\n$OD$ 在 $\\angle BOC$ 内部 → $\\angle COD=\\angle BOC-\\angle BOD=60°-20°=40°$。\n\n【要点】角平分线先给一半，再按「内部相减」求小角。"},
  {"id":"cf-fi-18","chapter":"ch-expr","method":"m-pattern","tier":"l3","kind":"fill","score":2,"tierName":"填空 · 图形规律（用含 n 式子表示）","errorTags":["method"],"stem":"边长相等的小正方形组成一组有规律的图案，其中部分涂有阴影。第 1 个图案有 $3$ 个阴影小正方形，第 2 个有 $5$ 个，第 3 个有 $7$ 个……则第 $n$ 个图案中涂有阴影的小正方形个数为 ___（用含 $n$ 的式子表示）。","steps":[{"label":"找公差","ask":"阴影数 $3,5,7,\\cdots$，公差是？","type":"fill","accept":["2"],"answer":"2","score":1,"hint":"$5-3=2$。","why":"公差 $2$。"},{"label":"写通项","ask":"$a_n=3+2(n-1)$，化简得？","type":"fill","accept":["2n+1","2n+1个"],"answer":"2n+1","score":1,"hint":"$3+2n-2$。","why":"$2n+1$。"}],"solution":"阴影数构成等差数列：$3,5,7,\\cdots$，公差 $d=2$。\n$a_n=3+2(n-1)=2n+1$。\n\n【验证】$n=1\\to3$ ✓，$n=2\\to5$ ✓，$n=3\\to7$ ✓\n【要点】通项 $=a_1+(n-1)d$，代完要化简。"},
  {"id":"cf-fi-19","chapter":"ch-expr","method":"m-substitute","tier":"l2","kind":"fill","score":2,"tierName":"填空 · 代数式求值（整体代入）","errorTags":["method"],"stem":"若 $a^{2}+a=3$，则 $2a^{2}+2a-7$ 的值为 ___。","steps":[{"label":"提公因数","ask":"$2a^{2}+2a=2(a^{2}+a)$。代入 $a^{2}+a=3$。","type":"fill","accept":["-1"],"answer":"-1","score":2,"hint":"$2\\times3-7$。","why":"$6-7=-1$。"}],"solution":"$2a^{2}+2a-7=2(a^{2}+a)-7$。\n代入 $a^{2}+a=3$：$2\\times3-7=6-7=-1$。\n\n【要点】不要试图解出 $a$（$a^{2}+a=3$ 在初一解不了）。正确做法是「提公因数凑出整体」。"},
  {"id":"cf-fi-20","chapter":"ch-op","method":"m-magic-sum","tier":"l3","kind":"fill","score":2,"tierName":"填空 · 数字填图定等和（真题第 16 题，3/3 年）","errorTags":["method"],"stem":"将 $1,2,3,4,5,6,7,8$ 这八个数填入「幻圆」的八个圆圈，使大圆上、小圆上以及两条直径上的四个数之和都相等（每个圆圈恰属两条线）。则每条线上的四数之和为 ___。","steps":[{"label":"算总和","ask":"$1+2+\\cdots+8$ 等于？","type":"fill","accept":["36"],"answer":"36","score":1,"hint":"$\\dfrac{8\\times9}{2}$。","why":"$36$。"},{"label":"定等和","ask":"四条线、每点属两条线 → $4S=2\\times36$。$S=$？","type":"fill","accept":["18"],"answer":"18","score":1,"hint":"$72\\div4$。","why":"$S=18$。这与真题给的条件「和都等于 18」一致。"}],"solution":"八数之和 $=1+2+\\cdots+8=36$。\n每个圆圈恰属两条线 → 四条线之和 $=2\\times36=72$。\n每条线的和 $S=72\\div4=18$。\n\n【要点】这就是真题第 16 题的核心一步。定出等和 18 之后，剩下的填数才可能做——不定等和就硬凑，是这类题失分的主因。"},
  {"id":"cf-ch-21","chapter":"ch-op","calcType":"power","method":"m-op-order","tier":"l1","kind":"choice","score":2,"tierName":"选择 · 乘方意义辨析","errorTags":["concept"],"stem":"下列各式中，计算结果为负数的是（　）","options":["$(-2)^{3}$","$(-2)^{2}$","$-(-2)$","$|-2|$"],"steps":[{"label":"定符号","ask":"$(-2)^{3}$ 是负数的奇次幂，符号为？","type":"choice","options":["$(-2)^{3}$","$(-2)^{2}$","$-(-2)$","$|-2|$"],"key":0,"score":2,"hint":"负数奇次幂为负，偶次幂为正。","why":"$(-2)^{3}=-8<0$。其余：$(-2)^{2}=4$、$-(-2)=2$、$|-2|=2$ 都是正数。"}],"solution":"$(-2)^{3}=-8<0$ ✓\n$(-2)^{2}=4>0$\n$-(-2)=2>0$\n$|-2|=2>0$\n\n【要点】负数奇次幂为负、偶次幂为正。"},
  {"id":"cf-ch-22","chapter":"ch-op","calcType":"mix","method":"m-op-order","tier":"l1","kind":"choice","score":2,"tierName":"选择 · 运算顺序","errorTags":["calc"],"stem":"计算 $-2^{2}+3$ 的结果是（　）","options":["$-1$","$7$","$1$","$-7$"],"steps":[{"label":"先乘方","ask":"$-2^{2}$ 中负号在括号外，底数是 $2$，故 $-2^{2}=$？","type":"choice","options":["$-1$","$7$","$1$","$-7$"],"key":0,"score":2,"hint":"$-2^{2}=-(2^{2})=-4$，再加 $3$。","why":"$-2^{2}=-4$，$-4+3=-1$。"}],"solution":"$-2^{2}=-(2\\times2)=-4$（负号在括号外，不参与乘方）。\n$-4+3=-1$。\n\n【易错】把 $-2^{2}$ 算成 $4$（误以为底数是 $-2$），会得 $7$。"},
  {"id":"cf-fi-21","chapter":"ch-op","calcType":"power","method":"m-op-order","tier":"l1","kind":"fill","score":2,"tierName":"填空 · 乘方与符号","errorTags":["calc"],"stem":"计算：$(-3)^{2}-(-2)^{3}=$ ___。","steps":[{"label":"分别算乘方","ask":"$(-3)^{2}=9$，$(-2)^{3}=-8$。$9-(-8)=$？","type":"fill","accept":["17"],"answer":"17","score":2,"hint":"减去负的等于加上正的。","why":"$9-(-8)=9+8=17$。"}],"solution":"$(-3)^{2}=9$（偶次幂为正）\n$(-2)^{3}=-8$（奇次幂为负）\n$9-(-8)=9+8=17$。\n\n【易错】$9-(-8)$ 写成 $9-8=1$，忘了「减负变加」。"},
  {"id":"cf-fi-22","chapter":"ch-op","calcType":"mix","method":"m-sign-rule","tier":"l1","kind":"fill","score":2,"tierName":"填空 · 多个负数相乘","errorTags":["sign"],"stem":"计算：$(-1)\\times(-2)\\times(-3)\\times(-4)=$ ___。","steps":[{"label":"数负号","ask":"四个负号（偶数个），积的符号是？","type":"fill","accept":["24"],"answer":"24","score":2,"hint":"偶数个负号得正，再算 $1\\times2\\times3\\times4$。","why":"四个负号，偶数个，积为正：$24$。"}],"solution":"四个负数相乘，负号个数为偶数 → 积为正。\n$1\\times2\\times3\\times4=24$。\n\n【要点】先定符号（奇负偶正），再算绝对值。"},
  {"id":"cf-fi-23","chapter":"ch-op","calcType":"mix","method":"m-op-order","tier":"l2","kind":"fill","score":2,"tierName":"填空 · 分配律简算","errorTags":["calc"],"stem":"用简便方法计算：$\\left(-\\dfrac{1}{2}+\\dfrac{1}{3}-\\dfrac{1}{6}\\right)\\times(-12)=$ ___。","steps":[{"label":"分配律展开","ask":"$(-\\dfrac12)\\times(-12)=6$，$\\dfrac13\\times(-12)=-4$，$(-\\dfrac16)\\times(-12)=2$。求和？","type":"fill","accept":["4"],"answer":"4","score":2,"hint":"$6-4+2$。","why":"$6+(-4)+2=4$。"}],"solution":"用分配律逐项相乘：\n$(-\\dfrac12)\\times(-12)=6$\n$\\dfrac13\\times(-12)=-4$\n$(-\\dfrac16)\\times(-12)=2$\n合计 $6-4+2=4$。\n\n【要点】括号内分母都是 12 的因数，用分配律比先通分快。"},
  {"id":"cf-fi-24","chapter":"ch-op","calcType":"power","method":null,"tier":"l1","kind":"fill","score":2,"tierName":"填空 · 科学记数法还原","errorTags":["concept"],"stem":"把 $3.6\\times10^{5}$ 写成原数，结果是 ___。","steps":[{"label":"移小数点","ask":"$\\times10^{5}$ 表示小数点向右移 5 位。结果？","type":"fill","accept":["360000"],"answer":"360000","score":2,"hint":"$3.6\\to36\\to360\\to3600\\to36000\\to360000$。","why":"$360000$。"}],"solution":"$3.6\\times10^{5}=360000$（小数点右移 5 位）。\n\n【要点】$10^{n}$（$n>0$）把小数点右移 $n$ 位；$10^{-n}$ 左移 $n$ 位。"},
  {"id":"cf-fi-25","chapter":"ch-op","calcType":"power","method":null,"tier":"l2","kind":"fill","score":2,"tierName":"填空 · 近似数有效数字","errorTags":["concept"],"stem":"用四舍五入法把 $0.02964$ 精确到 $0.001$，所得近似数为 ___。","steps":[{"label":"看下一位","ask":"精确到 $0.001$（三位小数）即保留 $0.029$，下一位是 $6\\ge5$，进位。结果？","type":"fill","accept":["0.030"],"answer":"0.030","score":2,"hint":"$0.0296\\to0.030$，末位的 0 不能省。","why":"$0.030$。"}],"solution":"$0.02964$ 精确到 $0.001$：看第四位 $6\\ge5$，进位，$0.029\\to0.030$。\n\n【易错】写成 $0.03$——精确到千分位必须保留三位小数，末位的 $0$ 体现精度，不能省略。"},
  {"id":"cf-fi-26","chapter":"ch-op","calcType":"mix","method":"m-op-order","tier":"l2","kind":"fill","score":2,"tierName":"填空 · 混合运算顺序","errorTags":["calc"],"stem":"计算：$-6\\div(-2)\\times\\dfrac{1}{3}=$ ___。","steps":[{"label":"从左到右","ask":"乘除同级，从左到右：$-6\\div(-2)=3$，再 $\\times\\dfrac13$。结果？","type":"fill","accept":["1"],"answer":"1","score":2,"hint":"$3\\times\\dfrac13$。","why":"$1$。"}],"solution":"$-6\\div(-2)\\times\\dfrac13$：乘除同级，从左到右。\n$-6\\div(-2)=3$，$3\\times\\dfrac13=1$。\n\n【易错】先算 $(-2)\\times\\dfrac13$，会得到不同结果——同级运算必须从左到右。"},
  {"id":"cf-ch-23","chapter":"ch-op","calcType":"power","method":null,"tier":"l2","kind":"choice","score":2,"tierName":"选择 · 近似数精确度","errorTags":["concept"],"stem":"近似数 $2.40\\times10^{4}$ 精确到（　）","options":["百位","千位","十分位","个位"],"steps":[{"label":"还原看末位","ask":"$2.40\\times10^{4}=24000$。$2.40$ 的末位 $0$ 在还原后对应哪一位？","type":"choice","options":["百位","千位","十分位","个位"],"key":0,"score":2,"hint":"$2.40$ 末位是百分位，乘 $10^{4}$ 后右移 4 位 → 百位。","why":"$2.40\\times10^{4}=24000$，末位 $0$ 落在百位，故精确到百位。"}],"solution":"$2.40\\times10^{4}=24000$。\n$2.40$ 的末位（百分位）在乘 $10^{4}$ 后右移 4 位，落到**百位**。\n故精确到百位。\n\n【要点】带科学记数法的近似数，精确度看 $a$ 的末位在还原后落在哪一位，不能只看 $a$ 本身。"},
  {"id":"cf-ch-24","chapter":"ch-eq","calcType":"eq","method":"m-eq-5steps","tier":"l1","kind":"choice","score":2,"tierName":"选择 · 方程解的概念","errorTags":["concept"],"stem":"下列方程中，解为 $x=3$ 的是（　）","options":["$2x-1=5$","$x+3=0$","$3x=1$","$x-3=6$"],"steps":[{"label":"代入验证","ask":"把 $x=3$ 逐项代入，哪个成立？","type":"choice","options":["$2x-1=5$","$x+3=0$","$3x=1$","$x-3=6$"],"key":0,"score":2,"hint":"$2\\times3-1=5$ ✓","why":"$2\\times3-1=5$ 成立。其余：$3+3=6\\ne0$、$3\\times3=9\\ne1$、$3-3=0\\ne6$。"}],"solution":"逐项代入 $x=3$：\n$2\\times3-1=5$ ✓\n$3+3=6\\ne0$ ✗\n$3\\times3=9\\ne1$ ✗\n$3-3=0\\ne6$ ✗\n\n【要点】「是方程的解」= 代入后等式成立，逐项验算最快。"},
  {"id":"cf-ch-25","chapter":"ch-eq","calcType":"eq","method":"m-eq-5steps","tier":"l2","kind":"choice","score":2,"tierName":"选择 · 等式性质辨析","errorTags":["concept"],"stem":"下列变形正确的是（　）","options":["由 $a=b$ 得 $a+2=b+2$","由 $a=b$ 得 $\\dfrac{a}{c}=\\dfrac{b}{c}$（$c$ 任意）","由 $ac=bc$ 得 $a=b$","由 $a=b$ 得 $a-2=b+2$"],"steps":[{"label":"逐项验条件","ask":"哪一项的变形在任何情况下都成立？","type":"choice","options":["由 $a=b$ 得 $a+2=b+2$","由 $a=b$ 得 $\\dfrac{a}{c}=\\dfrac{b}{c}$（$c$ 任意）","由 $ac=bc$ 得 $a=b$","由 $a=b$ 得 $a-2=b+2$"],"key":0,"score":2,"hint":"B 需要 $c\\ne0$；C 需要 $c\\ne0$；D 两边加的数不同。","why":"等式两边同加同一个数仍成立（性质 1）。B、C 都要求 $c\\ne0$，D 两边加的数不同。"}],"solution":"A 正确：等式两边同加 $2$，等式仍成立（等式性质 1）。\n\n【逐项错因】\n· B：$c=0$ 时无意义（除数不能为 0）\n· C：$c=0$ 时 $0=0$ 恒成立，推不出 $a=b$\n· D：左边 $-2$、右边 $+2$，不是同一个数"},
  {"id":"cf-ch-26","chapter":"ch-eq","calcType":"eq","method":"m-eq-5steps","tier":"l1","kind":"choice","score":2,"tierName":"选择 · 移项变号","errorTags":["sign"],"stem":"方程 $3x-5=7$ 移项后正确的是（　）","options":["$3x=7+5$","$3x=7-5$","$3x-7=5$","$3x=5-7$"],"steps":[{"label":"移项要变号","ask":"$-5$ 从左边移到右边，符号怎么变？","type":"choice","options":["$3x=7+5$","$3x=7-5$","$3x-7=5$","$3x=5-7$"],"key":0,"score":2,"hint":"移项变号：$-5$ 移到右边变 $+5$。","why":"$3x=7+5=12$，$x=4$。"}],"solution":"$3x-5=7$\n移项（$-5$ 移到右边变 $+5$）：$3x=7+5=12$\n$x=4$\n\n【要点】移项必须变号，这是最高频的失分点。验证：$3\\times4-5=7$ ✓"},
  {"id":"cf-fi-27","chapter":"ch-eq","calcType":"eq","method":"m-eq-5steps","tier":"l1","kind":"fill","score":2,"tierName":"填空 · 解简单方程","errorTags":["calc"],"stem":"方程 $2x+7=1$ 的解是 $x=$ ___。","steps":[{"label":"移项求解","ask":"$2x=1-7=-6$，$x=$？","type":"fill","accept":["-3"],"answer":"-3","score":2,"hint":"$-6\\div2$。","why":"$x=-3$。"}],"solution":"$2x+7=1$\n$2x=1-7=-6$\n$x=-3$\n\n【验证】$2\\times(-3)+7=-6+7=1$ ✓"},
  {"id":"cf-fi-28","chapter":"ch-eq","calcType":"eq","method":"m-eq-5steps","tier":"l2","kind":"fill","score":2,"tierName":"填空 · 解方程（去括号）","errorTags":["calc"],"stem":"方程 $3(x-1)=2(x+1)$ 的解是 $x=$ ___。","steps":[{"label":"去括号再移项","ask":"$3x-3=2x+2$ → $3x-2x=2+3$ → $x=$？","type":"fill","accept":["5"],"answer":"5","score":2,"hint":"移项：$3x-2x=2+3$。","why":"$x=5$。"}],"solution":"$3(x-1)=2(x+1)$\n去括号：$3x-3=2x+2$\n移项：$3x-2x=2+3$\n$x=5$\n\n【验证】$3\\times4=12$，$2\\times6=12$ ✓"},
  {"id":"cf-fi-29","chapter":"ch-eq","calcType":"eq","method":"m-eq-5steps","tier":"l2","kind":"fill","score":2,"tierName":"填空 · 解方程（去分母）","errorTags":["calc"],"stem":"方程 $\\dfrac{x}{2}+\\dfrac{x}{3}=5$ 的解是 $x=$ ___。","steps":[{"label":"去分母","ask":"两边乘 $6$：$3x+2x=30$，$5x=30$。$x=$？","type":"fill","accept":["6"],"answer":"6","score":2,"hint":"$30\\div5$。","why":"$x=6$。"}],"solution":"$\\dfrac{x}{2}+\\dfrac{x}{3}=5$\n两边乘 $6$（最小公倍数）：$3x+2x=30$\n$5x=30$\n$x=6$\n\n【验证】$3+2=5$ ✓\n【易错】去分母时漏乘不含分母的项（右边的 $5$ 也要乘 6）。"},
  {"id":"cf-fi-30","chapter":"ch-eq","calcType":"eq","method":"m-eq-param","tier":"l2","kind":"fill","score":2,"tierName":"填空 · 方程解求参数","errorTags":["concept"],"stem":"若 $x=-2$ 是方程 $ax+5=1$ 的解，则 $a=$ ___。","steps":[{"label":"代入","ask":"$-2a+5=1$，$-2a=-4$。$a=$？","type":"fill","accept":["2"],"answer":"2","score":2,"hint":"$-4\\div(-2)$。","why":"$a=2$。"}],"solution":"把 $x=-2$ 代入 $ax+5=1$：\n$a\\times(-2)+5=1$\n$-2a=-4$\n$a=2$\n\n【验证】$2\\times(-2)+5=1$ ✓"},
  {"id":"cf-ch-27","chapter":"ch-eq","method":"m-eq-model","tier":"l2","kind":"choice","score":2,"tierName":"选择 · 列方程（和差倍）","errorTags":["express"],"stem":"某数的 $3$ 倍减去 $4$ 等于该数的 $2$ 倍加 $5$，设该数为 $x$，则方程为（　）","options":["$3x-4=2x+5$","$3x+4=2x-5$","$3x-4=2x-5$","$3(x-4)=2(x+5)$"],"steps":[{"label":"逐句翻译","ask":"「$3$ 倍减 $4$」= $3x-4$；「$2$ 倍加 $5$」= $2x+5$。方程？","type":"choice","options":["$3x-4=2x+5$","$3x+4=2x-5$","$3x-4=2x-5$","$3(x-4)=2(x+5)$"],"key":0,"score":2,"hint":"「减去 4」在 $3x$ 之后，不是 $3(x-4)$。","why":"$3x-4=2x+5$。解得 $x=9$。"}],"solution":"「某数的 $3$ 倍减去 $4$」→ $3x-4$\n「该数的 $2$ 倍加 $5$」→ $2x+5$\n方程：$3x-4=2x+5$\n解得 $x=9$。\n\n【易错】写成 $3(x-4)$——那是「某数减 4 后的 3 倍」，语序不同。"},
  {"id":"cf-fi-31","chapter":"ch-eq","method":"m-eq-model","tier":"l2","kind":"fill","score":2,"tierName":"填空 · 列方程（行程）","errorTags":["express"],"stem":"甲、乙两地相距 $180$ 千米，一辆汽车从甲地开往乙地，每小时行 $60$ 千米，则到达乙地需要 ___ 小时。","steps":[{"label":"时间=路程÷速度","ask":"$180\\div60=$？","type":"fill","accept":["3"],"answer":"3","score":2,"hint":"$180\\div60$。","why":"$3$ 小时。"}],"solution":"时间 $=$ 路程 $\\div$ 速度 $=180\\div60=3$（小时）。\n\n【要点】行程三量关系：路程 $=$ 速度 $\\times$ 时间。"},
  {"id":"cf-fi-32","chapter":"ch-eq","method":"m-eq-model","tier":"l2","kind":"fill","score":2,"tierName":"填空 · 列方程（利润）","errorTags":["express"],"stem":"某商品进价 $80$ 元，售价 $100$ 元，则利润率是 ___ $\\%$。","steps":[{"label":"利润率公式","ask":"利润率 $=\\dfrac{售价-进价}{进价}$。代入？","type":"fill","accept":["25","25%"],"answer":"25","score":2,"hint":"$\\dfrac{100-80}{80}=\\dfrac{20}{80}$。","why":"$25\\%$。"}],"solution":"利润率 $=\\dfrac{售价-进价}{进价}=\\dfrac{100-80}{80}=\\dfrac{20}{80}=25\\%$。\n\n【易错】分母用售价（应为进价），会得 $20\\%$。"},
  {"id":"cf-ch-28","chapter":"ch-eq","calcType":"eq","method":"m-eq-param","tier":"l2","kind":"choice","score":2,"tierName":"选择 · 一元一次方程定义","errorTags":["concept"],"stem":"下列方程中，是一元一次方程的是（　）","options":["$2x+1=0$","$x^{2}=1$","$\\dfrac{1}{x}=2$","$x+y=3$"],"steps":[{"label":"验三条件","ask":"一元一次方程要求：只含一个未知数、未知数次数为 1、是整式方程。哪个满足？","type":"choice","options":["$2x+1=0$","$x^{2}=1$","$\\dfrac{1}{x}=2$","$x+y=3$"],"key":0,"score":2,"hint":"B 是二次；C 分母含未知数（分式方程）；D 有两个未知数。","why":"$2x+1=0$ 满足三条件。"}],"solution":"$2x+1=0$：一个未知数 $x$、次数 1、整式 ✓\n\n【逐项排除】\n· $x^{2}=1$：次数 2（二次）\n· $\\dfrac1x=2$：分母含未知数，是分式方程\n· $x+y=3$：两个未知数（二元）"},
  {"id":"cf-fi-33","chapter":"ch-eq","calcType":"eq","method":"m-eq-5steps","tier":"l2","kind":"fill","score":2,"tierName":"填空 · 检验方程的解","errorTags":["concept"],"stem":"检验 $x=2$ 是否为方程 $5x-3=2x+3$ 的解：把 $x=2$ 代入，左边 $=$ ___，右边 $=$ ___，故 $x=2$ ___（填「是」或「不是」）该方程的解。","steps":[{"label":"代两边","ask":"左边 $5\\times2-3=7$，右边 $2\\times2+3=7$。相等吗？","type":"fill","accept":["是","7,7,是","7和7是"],"answer":"是","score":2,"hint":"两边都等于 7，相等。","why":"左边 $=7$，右边 $=7$，相等，故 $x=2$ 是方程的解。"}],"solution":"左边 $=5\\times2-3=7$\n右边 $=2\\times2+3=7$\n左边 $=$ 右边，故 $x=2$ 是方程的解。\n\n【要点】检验要把解分别代入左右两边，不能只代一边。"},
  {"id":"cf-ch-29","chapter":"ch-rational","method":"m-numberline-dist","tier":"l3","kind":"choice","score":2,"tierName":"选择 · 加权距离和最小（真题 2023-24 第 8 题）","errorTags":["method"],"stem":"某乡镇五户居民依次住在同一条笔直小道边的 A、B、C、D、E 处，五户人数依次为 $1,2,3,3,2$ 人。现要在这条小道上新建一个便民服务点 $M$，使所有居民到服务点的距离之和最小（每户所有人都要计入），则 $M$ 应建在（　）","options":["C 处","B 处","D 处","A 处"],"steps":[{"label":"按人数加权找中位","ask":"累计人数：A=1、B=3、C=6、D=9、E=11。总人数 11，中位在第 6 人，落在哪一处？","type":"choice","options":["C 处","B 处","D 处","A 处"],"key":0,"score":2,"hint":"第 6 人恰好是 C 处的最后一人（累计到 C 为 6 人）。","why":"累计到 C 处恰好 6 人 ≥ 总人数一半（5.5），故中位点落在 C 处，$M$ 建在 C 处距离和最小。"}],"solution":"这类题的关键是**加权中位数**：把每户人数看作权重，找累计权重过半的位置。\n\n累计人数：A=1、B=1+2=3、C=3+3=6、D=6+3=9、E=9+2=11。\n总人数 11，一半是 5.5。累计到 C 处为 6 > 5.5，**中位点落在 C**。\n\n【验证】分别算各点距离和（人数×距离）：\n· 建在 B：$1\\times1+2\\times0+3\\times1+3\\times2+2\\times3=1+0+3+6+6=16$\n· 建在 C：$1\\times2+2\\times1+3\\times0+3\\times1+2\\times2=2+2+0+3+4=11$ ✓ 最小\n· 建在 D：$1\\times3+2\\times2+3\\times1+3\\times0+2\\times1=3+4+3+0+2=12$\n\n【要点】不加权时中位数在 C、D 之间任一点都最优；加权后中位数唯一落在 C。这是 2023-24 卷的新题型。"},
    {"id":"cf-fi-34","chapter":"ch-rational","method":"m-numberline-dist","tier":"l3","kind":"fill","score":2,"tierName":"填空 · 加权距离和（变式）","errorTags":["method"],"stem":"数轴上依次有 $A(-2)$、$B(0)$、$C(3)$ 三点，分别有 $2,1,3$ 个单位重量。若在数轴上放一个支点，使「每点重量 × 到支点距离」之和最小，则这个最小值为 ___。","steps":[{"label":"加权中位找区间","ask":"总重量 $6$，一半为 $3$。累计重量：A 处 $2$、B 处 $3$、C 处 $6$。累计到 B 恰好达到一半，说明最优点在？","type":"fill","accept":["13"],"answer":"13","score":2,"hint":"累计到 B 恰好等于一半 → 最优点是 B 到 C 之间的整段区间，区间内任一点加权距离和都是 13。","why":"B(0) 到 C(3) 之间任一点，加权距离和恒为 $13$。取 B 验算：$2\\times2+1\\times0+3\\times3=13$。"}],"solution":"总重量 $6$，一半为 $3$。累计重量：A 处 $2$、B 处 $2+1=3$、C 处 $6$。\n累计到 B **恰好等于一半**（$3=3$）——这是「平台」情形：最优点不是单点，而是 **B 到 C 之间的整段区间**。\n\n区间内任一点加权距离和都相同。取支点在 B(0)：\n$2\\times|{-2}-0|+1\\times|0-0|+3\\times|3-0|=2\\times2+0+3\\times3=4+9=13$。\n\n【验证（逐点）】\n· 支点在 A(-2)：$0+1\\times2+3\\times5=17$\n· 支点在 B(0)：$13$ ✓\n· 支点在 $x=1$：$2\\times3+1\\times1+3\\times2=6+1+6=13$ ✓\n· 支点在 C(3)：$2\\times5+1\\times3+0=13$ ✓\n· 支点在 E 外（如 $x=4$）：$2\\times6+1\\times4+3\\times1=12+4+3=19$ ↑ 变大\n\n【要点】累计权重**恰好等于一半**时，最优点是区间而非单点——这是加权中位数与普通中位数的关键差别。"},
  {"id":"cf-fi-35","chapter":"ch-geo","method":"m-geo-model","tier":"l2","kind":"fill","score":2,"tierName":"填空 · 几何建模（周长表达式）","errorTags":["express"],"stem":"一块长方形场地长为 $a$、宽为 $b$（$a>b$）。在长为 $a$ 的边上截取一段长 $x$，以这段为一边在场地内部画一个小长方形，其宽为 $c$。则剩余「U 形」区域的面积用含 $a,b,x,c$ 的式子表示为 ___。","steps":[{"label":"大面积减小面积","ask":"大长方形面积 $ab$，内部小长方形面积 $xc$。U 形区域面积？","type":"fill","accept":["ab-xc","ab−xc"],"answer":"ab-xc","score":2,"hint":"U 形 = 大长方形挖掉内部小长方形。","why":"$ab-xc$。"}],"solution":"U 形区域 = 大长方形面积 $-$ 内部小长方形面积。\n$=ab-xc$。\n\n【要点】几何建模第一步永远是「用字母把各段长度表示出来」，再套面积/周长公式。"},
  {"id":"cf-fi-36","chapter":"ch-geo","method":"m-geo-model","tier":"l3","kind":"fill","score":2,"tierName":"填空 · 几何建模（内圈长）","errorTags":["express","method"],"stem":"U 形赛道：长方形场地长 $a$、宽 $b$。在长为 $a$ 的边上截取长 $x$，以这段为一边向内部画一个宽为 $c$ 的小长方形，形成「U」形。小长方形在场地内部的**三条线段之和**称为「内圈长」。用含 $a,b,x,c$ 的式子表示内圈长：___。","steps":[{"label":"数三条线段","ask":"内部三条线段是：两条长 $c$ 的竖段 + 一条长 $x$ 的横段。合计？","type":"fill","accept":["x+2c","2c+x"],"answer":"x+2c","score":2,"hint":"两条侧边各 $c$，底边 $x$。","why":"内圈长 $=x+2c$。"}],"solution":"小长方形在场地内部的三条线段：\n· 两条侧边，各长 $c$\n· 一条底边，长 $x$\n内圈长 $=c+c+x=x+2c$。\n\n【要点】真题 2024-25 第 22 题就是这个结构。关键是把「内圈长」的定义逐字读准——只数**内部**的三条，不数贴边的那条。"},
  {"id":"cf-ch-30","chapter":"ch-geo","method":"m-geo-model","tier":"l3","kind":"choice","score":2,"tierName":"选择 · 几何建模（比较内圈长）","errorTags":["method","express"],"stem":"两种 U 形赛道设计：方案一在长 $a$ 的边上截取 $x$、宽 $c$；方案二在宽 $b$ 的边上截取 $y$、宽 $c$。若两种设计的内圈长相同，且 $x>y$，则 $c$ 与两方案宽度的关系是（　）","options":["两方案内圈长都是 $x+2c$ 与 $y+2c$，相等则 $x=y$，与 $x>y$ 矛盾","两方案内圈长都是 $2x+c$ 与 $2y+c$","无法比较","内圈长与 $c$ 无关"],"steps":[{"label":"写出两方案内圈长","ask":"方案一 $x+2c$，方案二 $y+2c$。若相等且 $x>y$，会怎样？","type":"choice","options":["矛盾，故两方案内圈长不可能相等","一定相等","与 $c$ 无关"],"key":0,"score":2,"hint":"$x+2c=y+2c\\Rightarrow x=y$，与 $x>y$ 矛盾。","why":"$x+2c=y+2c$ 推出 $x=y$，与题设 $x>y$ 矛盾。故两方案内圈长不可能相等。"}],"solution":"方案一内圈长 $=x+2c$，方案二内圈长 $=y+2c$。\n若两者相等：$x+2c=y+2c\\Rightarrow x=y$，与题设 $x>y$ **矛盾**。\n故两方案内圈长不可能相等。\n\n【要点】真题 2024-25 第 22 题第（2）问就是考「先设相等、再推出矛盾」这种说理方式，不是硬算。"},
  {"id":"cf-ch-31","chapter":"ch-expr","method":"m-newdef","tier":"l3","kind":"choice","score":2,"tierName":"选择 · 阅读理解（方法迁移）","errorTags":["method"],"stem":"【阅读材料】判断一个数是否为 $9$ 的倍数，可用如下方法：把这个数各位数字相加，若和是 $9$ 的倍数，则原数是 $9$ 的倍数。例如 $738$：$7+3+8=18$，$18$ 是 $9$ 的倍数，故 $738$ 是 $9$ 的倍数。\n按此方法，下列判断正确的是（　）","options":["$246$ 是 $9$ 的倍数","$246$ 不是 $9$ 的倍数","该方法对任何数都不成立","无法判断"],"steps":[{"label":"照做一遍","ask":"$246$：$2+4+6=12$。$12$ 是 $9$ 的倍数吗？","type":"choice","options":["不是，故 $246$ 不是 $9$ 的倍数","是，故 $246$ 是 $9$ 的倍数"],"key":0,"score":2,"hint":"$12\\div9$ 除不尽。","why":"$2+4+6=12$，$12$ 不是 $9$ 的倍数，故 $246$ 不是 $9$ 的倍数。"}],"solution":"照材料的方法做：\n$246$：$2+4+6=12$。\n$12$ 不是 $9$ 的倍数（$12\\div9$ 除不尽），故 $246$ **不是** $9$ 的倍数。\n\n【要点】阅读理解题的第一步永远是「照材料的方法原样做一遍」，不要凭自己已有的知识直接判断。"},
  {"id":"cf-fi-37","chapter":"ch-expr","method":"m-newdef","tier":"l3","kind":"fill","score":2,"tierName":"填空 · 阅读理解（说理迁移）","errorTags":["method","express"],"stem":"【阅读材料】用「划掉末位、加上末位 $2$ 倍」的方法判断 $19$ 的倍数：$436\\to43+2\\times6=55\\to5+2\\times5=15$，$15$ 不是 $19$ 的倍数，故 $436$ 不是。\n请用同样的方法判断 $570$：第一次操作得到 ___，第二次操作得到 ___，故 $570$ ___（填「是」或「不是」）$19$ 的倍数。","steps":[{"label":"照做两步","ask":"$570$：划掉末位 $0$，$57+2\\times0=57$；再 $5+2\\times7=19$。$19$ 是 $19$ 的倍数吗？","type":"fill","accept":["是"],"answer":"是","score":2,"hint":"最后得到 $19$，正好是 $19$ 的 $1$ 倍。","why":"第一次 $57$，第二次 $19$，$19$ 是 $19$ 的倍数，故 $570$ 是 $19$ 的倍数。"}],"solution":"$570$：\n第一次：划掉末位 $0$，$57+2\\times0=57$。\n第二次：划掉末位 $7$，$5+2\\times7=19$。\n$19$ 是 $19$ 的倍数（$19=19\\times1$），故 $570$ **是** $19$ 的倍数。\n\n【验证】$570\\div19=30$ ✓\n【要点】材料里说「直到数变为 20 以内的数为止」，得到 $19$ 就停——不要继续做下去。"},
  {"id":"cf-ch-32","chapter":"ch-eq","method":null,"tier":"l1","kind":"choice","score":2,"tierName":"选择 · 方程与等式的关系","errorTags":["concept"],"stem":"下列说法正确的是（　）","options":["方程一定是等式","等式一定是方程","方程与等式没有关系","$3+2=5$ 是方程"],"steps":[{"label":"辨两个概念","ask":"方程的定义是「含未知数的等式」。那么方程与等式是什么关系？","type":"choice","options":["方程一定是等式","等式一定是方程","方程与等式没有关系","$3+2=5$ 是方程"],"key":0,"score":2,"hint":"方程 = 等式 + 含未知数。所以方程是等式的子集。","why":"方程一定是等式（因为定义要求是等式）；但等式不一定是方程（如 $3+2=5$ 无未知数）。"}],"solution":"方程的定义：**含有未知数的等式**。\n所以：方程 $\\subset$ 等式 —— 方程一定是等式，但等式不一定是方程。\n\n【逐项】\n· 「等式一定是方程」错：$3+2=5$ 是等式但没有未知数，不是方程\n· 「$3+2=5$ 是方程」错：没有未知数\n\n【要点】这是真题 2021-22 第 7 题、2023-24 第 7 题的共同基础——判断「变形是否等价」前，先分清方程与等式。"},
  {"id":"cf-ch-33","chapter":"ch-op","method":null,"tier":"l1","kind":"choice","score":2,"tierName":"选择 · 乘方符号","errorTags":["calc"],"stem":"$(-3)^{4}$ 与 $-3^{4}$ 的值分别是（　）","options":["$81$ 与 $-81$","$-81$ 与 $81$","$81$ 与 $81$","$-81$ 与 $-81$"],"steps":[{"label":"计算","ask":"计算结果是？","type":"choice","options":["$81$ 与 $-81$","$-81$ 与 $81$","$81$ 与 $81$","$-81$ 与 $-81$"],"key":0,"score":2,"hint":"$(-3)^{4}=81$：底数是 $-3$，偶次幂为正。\n$-3^{4}=-(3\\times3\\times3\\times3)=-81$：负号在括号外，不参与乘方。\n\n【易错】这是最高频的乘方陷阱——差一个括号，结果差个负号。","why":"$(-3)^{4}=81$：底数是 $-3$，偶次幂为正。\n$-3^{4}=-(3\\times3\\times3\\times3)=-81$：负号在括号外，不参与乘方。\n\n【易错】这是最高频的乘方陷阱——差一个括号，结果差个负号。"}]},
  {"id":"cf-ch-34","chapter":"ch-op","method":null,"tier":"l1","kind":"choice","score":2,"tierName":"选择 · 运算顺序","errorTags":["calc"],"stem":"计算 $12\\div(-3)\\times2$ 的结果是（　）","options":["$-8$","$-2$","$2$","$8$"],"steps":[{"label":"计算","ask":"计算结果是？","type":"choice","options":["$-8$","$-2$","$2$","$8$"],"key":0,"score":2,"hint":"$12\\div(-3)\\times2$：乘除同级，从左到右。\n$12\\div(-3)=-4$\n$-4\\times2=-8$\n\n【易错】先算 $(-3)\\times2=-6$，得 $12\\div(-6)=-2$。同级运算必须从左到右。","why":"$12\\div(-3)\\times2$：乘除同级，从左到右。\n$12\\div(-3)=-4$\n$-4\\times2=-8$\n\n【易错】先算 $(-3)\\times2=-6$，得 $12\\div(-6)=-2$。同级运算必须从左到右。"}]},
  {"id":"cf-ch-35","chapter":"ch-op","method":null,"tier":"l2","kind":"choice","score":2,"tierName":"选择 · 分配律","errorTags":["calc"],"stem":"用简便方法计算 $\\left(\\dfrac{1}{2}-\\dfrac{1}{3}+\\dfrac{1}{6}\\right)\\times(-12)$，结果是（　）","options":["$-4$","$4$","$-2$","$2$"],"steps":[{"label":"计算","ask":"计算结果是？","type":"choice","options":["$-4$","$4$","$-2$","$2$"],"key":0,"score":2,"hint":"用分配律：\n$\\dfrac{1}{2}\\times(-12)=-6$\n$-\\dfrac{1}{3}\\times(-12)=+4$\n$\\dfrac{1}{6}\\times(-12)=-2$\n合计 $-6+4-2=-4$。\n\n【要点】括号内分母都是 12 的因数，用分配律比通分快。","why":"用分配律：\n$\\dfrac{1}{2}\\times(-12)=-6$\n$-\\dfrac{1}{3}\\times(-12)=+4$\n$\\dfrac{1}{6}\\times(-12)=-2$\n合计 $-6+4-2=-4$。\n\n【要点】括号内分母都是 12 的因数，用分配律比通分快。"}]},
  {"id":"cf-fi-38","chapter":"ch-op","method":null,"tier":"l1","kind":"fill","score":2,"tierName":"填空 · 乘方计算","errorTags":["calc"],"stem":"计算：$(-1)^{2025}=$ ___。","steps":[{"label":"计算","ask":"填写结果","type":"fill","accept":["-1"],"answer":"-1","score":2,"hint":"$2025$ 是奇数，$(-1)$ 的奇次幂为 $-1$。","why":"$2025$ 是奇数，$(-1)$ 的奇次幂为 $-1$。"}],"solution":"$(-1)^{2025}=-1$：指数 $2025$ 是奇数，$(-1)$ 的奇次幂为 $-1$。\n\n【要点】$(-1)^{\\text{奇}}=-1$，$(-1)^{\\text{偶}}=1$。"},
  {"id":"cf-fi-39","chapter":"ch-op","method":null,"tier":"l1","kind":"fill","score":2,"tierName":"填空 · 绝对值与乘方","errorTags":["calc"],"stem":"计算：$|-2|^{3}-(-2)^{3}=$ ___。","steps":[{"label":"计算","ask":"填写结果","type":"fill","accept":["16"],"answer":"16","score":2,"hint":"$|-2|^{3}=2^{3}=8$，$(-2)^{3}=-8$，$8-(-2)^{3}=8+8=16$。","why":"$|-2|^{3}=2^{3}=8$，$(-2)^{3}=-8$，$8-(-2)^{3}=8+8=16$。"}],"solution":"$|-2|^{3}=2^{3}=8$\n$(-2)^{3}=-8$\n$8-(-8)=16$\n\n【要点】先算绝对值再乘方；减去负数变加法。"},
  {"id":"cf-fi-40","chapter":"ch-op","method":null,"tier":"l2","kind":"fill","score":2,"tierName":"填空 · 除法转乘法","errorTags":["calc"],"stem":"计算：$-\\dfrac{3}{4}\\div\\left(-\\dfrac{3}{8}\\right)=$ ___。","steps":[{"label":"计算","ask":"填写结果","type":"fill","accept":["2"],"answer":"2","score":2,"hint":"除以一个分数等于乘它的倒数：$-\\dfrac34\\times\\left(-\\dfrac83\\right)=2$。","why":"除以一个分数等于乘它的倒数：$-\\dfrac34\\times\\left(-\\dfrac83\\right)=2$。"}],"solution":"$-\\dfrac{3}{4}\\div\\left(-\\dfrac{3}{8}\\right)$\n$=-\\dfrac{3}{4}\\times\\left(-\\dfrac{8}{3}\\right)$\n$=2$\n\n【要点】负负得正，再约分。"},
  {"id":"cf-fi-41","chapter":"ch-op","method":null,"tier":"l2","kind":"fill","score":2,"tierName":"填空 · 混合运算","errorTags":["calc"],"stem":"计算：$-2^{2}+(-3)^{2}-|-4|=$ ___。","steps":[{"label":"计算","ask":"填写结果","type":"fill","accept":["1"],"answer":"1","score":2,"hint":"$-2^{2}=-4$，$(-3)^{2}=9$，$|-4|=4$。$-4+9-4=1$。","why":"$-2^{2}=-4$，$(-3)^{2}=9$，$|-4|=4$。$-4+9-4=1$。"}],"solution":"$-2^{2}=-4$（负号在括号外）\n$(-3)^{2}=9$\n$|-4|=4$\n$-4+9-4=1$\n\n【要点】三个易错点合在一题：括号外的负号、偶次幂、绝对值。"},
  {"id":"cf-fi-42","chapter":"ch-op","method":null,"tier":"l2","kind":"fill","score":2,"tierName":"填空 · 科学记数法运算","errorTags":["calc"],"stem":"计算：$(2\\times10^{3})\\times(3\\times10^{4})=$ ___（用科学记数法表示）。","steps":[{"label":"计算","ask":"填写结果","type":"fill","accept":["6×10^7","6*10^7","$6\\times10^{7}$"],"answer":"6×10^7","score":2,"hint":"系数相乘 $2\\times3=6$，指数相加 $3+4=7$，得 $6\\times10^{7}$。","why":"系数相乘 $2\\times3=6$，指数相加 $3+4=7$，得 $6\\times10^{7}$。"}],"solution":"$(2\\times10^{3})\\times(3\\times10^{4})=(2\\times3)\\times10^{3+4}=6\\times10^{7}$。\n\n【要点】科学记数法相乘：系数相乘、指数相加。注意结果系数要在 $[1,10)$ 内。"},
  {"id":"cf-fi-43","chapter":"ch-op","method":null,"tier":"l1","kind":"fill","score":2,"tierName":"填空 · 近似数","errorTags":["calc"],"stem":"用四舍五入法把 $5.6049$ 精确到 $0.01$，得 ___。","steps":[{"label":"计算","ask":"填写结果","type":"fill","accept":["5.60"],"answer":"5.60","score":2,"hint":"保留两位小数 $5.60$，第三位是 $4<5$ 舍去。","why":"保留两位小数 $5.60$，第三位是 $4<5$ 舍去。"}],"solution":"$5.6049$ 精确到 $0.01$（两位小数）：看第三位 $4<5$，舍去 → $5.60$。\n\n【易错】末位的 $0$ 不能省——它体现「精确到百分位」这个精度信息。"},
  {"id":"cf-ch-36","chapter":"ch-op","method":null,"tier":"l2","kind":"choice","score":2,"tierName":"选择 · 运算律适用","errorTags":["calc"],"stem":"下列计算正确的是（　）","options":["$(-8)\\div2\\times\\dfrac12=-8$","$(-8)\\div2\\times\\dfrac12=-2$","$(-8)\\div2\\times\\dfrac12=8$","$(-8)\\div2\\times\\dfrac12=-4$"],"steps":[{"label":"计算","ask":"计算结果是？","type":"choice","options":["$(-8)\\div2\\times\\dfrac12=-8$","$(-8)\\div2\\times\\dfrac12=-2$","$(-8)\\div2\\times\\dfrac12=8$","$(-8)\\div2\\times\\dfrac12=-4$"],"key":1,"score":2,"hint":"$(-8)\\div2\\times\\dfrac12$：乘除同级从左到右。\n$-8\\div2=-4$\n$-4\\times\\dfrac12=-2$\n\n【易错】先算 $2\\times\\dfrac12=1$，得 $-8\\div1=-8$。","why":"$(-8)\\div2\\times\\dfrac12$：乘除同级从左到右。\n$-8\\div2=-4$\n$-4\\times\\dfrac12=-2$\n\n【易错】先算 $2\\times\\dfrac12=1$，得 $-8\\div1=-8$。"}]},
  {"id":"cf-fi-44","chapter":"ch-op","method":null,"tier":"l2","kind":"fill","score":2,"tierName":"填空 · 带分数乘方","errorTags":["calc"],"stem":"计算：$\\left(-1\\dfrac{1}{2}\\right)^{2}=$ ___。","steps":[{"label":"计算","ask":"填写结果","type":"fill","accept":["9/4","2.25","2¼"],"answer":"9/4","score":2,"hint":"先化假分数：$-\\dfrac32$，平方得 $\\dfrac94$。","why":"先化假分数：$-\\dfrac32$，平方得 $\\dfrac94$。"}],"solution":"$\\left(-1\\dfrac{1}{2}\\right)^{2}=\\left(-\\dfrac{3}{2}\\right)^{2}=\\dfrac{9}{4}$。\n\n【易错】带分数必须先化假分数再乘方——直接把 $1$ 和 $\\dfrac12$ 分别平方会得 $1\\dfrac14$，是错的。"},
  {"id":"cf-fi-45","chapter":"ch-op","method":null,"tier":"l2","kind":"fill","score":2,"tierName":"填空 · 多负数相乘","errorTags":["calc"],"stem":"计算：$(-2)^{3}\\times(-3)\\times\\left(-\\dfrac{1}{2}\\right)=$ ___。","steps":[{"label":"计算","ask":"填写结果","type":"fill","accept":["-12"],"answer":"-12","score":2,"hint":"$(-2)^{3}=-8$；三个负号（$-8,-3,-\\dfrac12$）为奇数个，积为负。$8\\times3\\times\\dfrac12=12$，故 $-12$。","why":"$(-2)^{3}=-8$；三个负号（$-8,-3,-\\dfrac12$）为奇数个，积为负。$8\\times3\\times\\dfrac12=12$，故 $-12$。"}],"solution":"$(-2)^{3}=-8$\n负号共三个（奇数），积为负。\n$8\\times3\\times\\dfrac{1}{2}=12$\n故结果 $-12$。\n\n【要点】先数负号定符号，再算绝对值。"},
  {"id":"cf-fi-46","chapter":"ch-eq","method":null,"tier":"l1","kind":"fill","score":2,"tierName":"填空 · 解方程（移项）","errorTags":["calc"],"stem":"方程 $5x-3=2x+9$ 的解是 $x=$ ___。","steps":[{"label":"计算","ask":"填写结果","type":"fill","accept":["4"],"answer":"4","score":2,"hint":"移项：$5x-2x=9+3$，$3x=12$，$x=4$。","why":"移项：$5x-2x=9+3$，$3x=12$，$x=4$。"}],"solution":"$5x-3=2x+9$\n移项：$5x-2x=9+3$\n$3x=12$\n$x=4$\n\n【验证】左边 $5\\times4-3=17$，右边 $2\\times4+9=17$ ✓"},
  {"id":"cf-fi-47","chapter":"ch-eq","method":null,"tier":"l1","kind":"fill","score":2,"tierName":"填空 · 解方程（去括号）","errorTags":["calc"],"stem":"方程 $2(x+3)=3(x-1)$ 的解是 $x=$ ___。","steps":[{"label":"计算","ask":"填写结果","type":"fill","accept":["9"],"answer":"9","score":2,"hint":"去括号：$2x+6=3x-3$；移项：$6+3=3x-2x$，$x=9$。","why":"去括号：$2x+6=3x-3$；移项：$6+3=3x-2x$，$x=9$。"}],"solution":"$2(x+3)=3(x-1)$\n去括号：$2x+6=3x-3$\n移项：$6+3=3x-2x$\n$x=9$\n\n【验证】$2\\times12=24$，$3\\times8=24$ ✓"},
  {"id":"cf-fi-48","chapter":"ch-eq","method":null,"tier":"l2","kind":"fill","score":2,"tierName":"填空 · 解方程（去分母）","errorTags":["calc"],"stem":"方程 $\\dfrac{2x-1}{3}=\\dfrac{x+2}{2}$ 的解是 $x=$ ___。","steps":[{"label":"计算","ask":"填写结果","type":"fill","accept":["8"],"answer":"8","score":2,"hint":"两边乘 6：$2(2x-1)=3(x+2)$，$4x-2=3x+6$，$x=8$。","why":"两边乘 6：$2(2x-1)=3(x+2)$，$4x-2=3x+6$，$x=8$。"}],"solution":"$\\dfrac{2x-1}{3}=\\dfrac{x+2}{2}$\n两边乘 $6$：$2(2x-1)=3(x+2)$\n去括号：$4x-2=3x+6$\n$x=8$\n\n【验证】左边 $\\dfrac{15}{3}=5$，右边 $\\dfrac{10}{2}=5$ ✓"},
  {"id":"cf-fi-49","chapter":"ch-eq","method":null,"tier":"l2","kind":"fill","score":2,"tierName":"填空 · 解方程（双分母）","errorTags":["calc"],"stem":"方程 $\\dfrac{x+1}{2}-\\dfrac{x-1}{3}=1$ 的解是 $x=$ ___。","steps":[{"label":"计算","ask":"填写结果","type":"fill","accept":["1"],"answer":"1","score":2,"hint":"两边乘 6：$3(x+1)-2(x-1)=6$，$3x+3-2x+2=6$，$x+5=6$，$x=1$。","why":"两边乘 6：$3(x+1)-2(x-1)=6$，$3x+3-2x+2=6$，$x+5=6$，$x=1$。"}],"solution":"$\\dfrac{x+1}{2}-\\dfrac{x-1}{3}=1$\n两边乘 $6$：$3(x+1)-2(x-1)=6$\n去括号：$3x+3-2x+2=6$\n$x+5=6$\n$x=1$\n\n【易错】右边的 $1$ 也要乘 $6$，得 $6$ 不是 $1$。"},
  {"id":"cf-ch-37","chapter":"ch-eq","method":null,"tier":"l2","kind":"choice","score":2,"tierName":"选择 · 方程变形","errorTags":["calc"],"stem":"下列变形正确的是（　）","options":["由 $\\dfrac{x}{3}=2$ 得 $x=\\dfrac{2}{3}$","由 $\\dfrac{x}{3}=2$ 得 $x=6$","由 $2x=3$ 得 $x=\\dfrac{3}{2}$","由 $2x=3$ 得 $x=\\dfrac{2}{3}$"],"steps":[{"label":"计算","ask":"计算结果是？","type":"choice","options":["由 $\\dfrac{x}{3}=2$ 得 $x=\\dfrac{2}{3}$","由 $\\dfrac{x}{3}=2$ 得 $x=6$","由 $2x=3$ 得 $x=\\dfrac{3}{2}$","由 $2x=3$ 得 $x=\\dfrac{2}{3}$"],"key":1,"score":2,"hint":"$\\dfrac{x}{3}=2$：两边同乘 $3$，得 $x=6$。\n\n【易错】把「除以 3」和「乘 3」搞反，会得 $x=\\dfrac23$。验证：$\\dfrac{6}{3}=2$ ✓","why":"$\\dfrac{x}{3}=2$：两边同乘 $3$，得 $x=6$。\n\n【易错】把「除以 3」和「乘 3」搞反，会得 $x=\\dfrac23$。验证：$\\dfrac{6}{3}=2$ ✓"}]},
  {"id":"cf-fi-50","chapter":"ch-eq","method":null,"tier":"l2","kind":"fill","score":2,"tierName":"填空 · 方程解求参","errorTags":["calc"],"stem":"若 $x=3$ 是方程 $2x+a=7$ 的解，则 $a=$ ___。","steps":[{"label":"计算","ask":"填写结果","type":"fill","accept":["1"],"answer":"1","score":2,"hint":"代入：$6+a=7$，$a=1$。","why":"代入：$6+a=7$，$a=1$。"}],"solution":"把 $x=3$ 代入 $2x+a=7$：\n$2\\times3+a=7$\n$6+a=7$\n$a=1$\n\n【验证】$2\\times3+1=7$ ✓"},
  {"id":"cf-fi-51","chapter":"ch-eq","method":null,"tier":"l2","kind":"fill","score":2,"tierName":"填空 · 含参方程","errorTags":["calc"],"stem":"若关于 $x$ 的方程 $(k-2)x=5$ 有唯一解，则 $k$ 的取值范围是 $k\\ne$ ___。","steps":[{"label":"计算","ask":"填写结果","type":"fill","accept":["2"],"answer":"2","score":2,"hint":"唯一解要求一次项系数不为 0：$k-2\\ne0$，即 $k\\ne2$。","why":"唯一解要求一次项系数不为 0：$k-2\\ne0$，即 $k\\ne2$。"}],"solution":"方程 $(k-2)x=5$ 有唯一解，要求一次项系数不为 $0$：\n$k-2\\ne0$，即 $k\\ne2$。\n\n【要点】含参方程第一步永远是「检查系数是否可能为 0」——为 0 时要单独讨论。"},
  {"id":"cf-fi-52","chapter":"ch-eq","method":null,"tier":"l3","kind":"fill","score":2,"tierName":"填空 · 含参方程无解","errorTags":["calc"],"stem":"若关于 $x$ 的方程 $(m-1)x=3$ 无解，则 $m=$ ___。","steps":[{"label":"计算","ask":"填写结果","type":"fill","accept":["1"],"answer":"1","score":2,"hint":"无解要求 $m-1=0$ 且右边不为 0：$m=1$ 时方程变为 $0=3$，矛盾，无解。","why":"无解要求 $m-1=0$ 且右边不为 0：$m=1$ 时方程变为 $0=3$，矛盾，无解。"}],"solution":"$(m-1)x=3$ 无解，要求：\n系数为 $0$（$m-1=0$，即 $m=1$）**且**右边不为 $0$（$3\\ne0$ ✓）。\n故 $m=1$。\n\n【验证】$m=1$ 时方程变为 $0\\cdot x=3$，即 $0=3$，矛盾，无解 ✓"},
  {"id":"cf-fi-53","chapter":"ch-eq","method":null,"tier":"l2","kind":"fill","score":2,"tierName":"填空 · 方程应用题（和差）","errorTags":["calc"],"stem":"两个数的和是 $20$，其中一个数比另一个数大 $4$，则较小的数是 ___。","steps":[{"label":"计算","ask":"填写结果","type":"fill","accept":["8"],"answer":"8","score":2,"hint":"设较小数为 $x$，则 $x+(x+4)=20$，$2x=16$，$x=8$。","why":"设较小数为 $x$，则 $x+(x+4)=20$，$2x=16$，$x=8$。"}],"solution":"设较小的数为 $x$，较大的为 $x+4$。\n$x+(x+4)=20$\n$2x+4=20$\n$2x=16$\n$x=8$\n\n【验证】$8+12=20$ ✓"},
  {"id":"cf-fi-54","chapter":"ch-eq","method":null,"tier":"l2","kind":"fill","score":2,"tierName":"填空 · 方程应用题（利润）","errorTags":["calc"],"stem":"某商品进价 $120$ 元，按标价的八折出售仍可获利 $20\\%$，则标价是 ___ 元。","steps":[{"label":"计算","ask":"填写结果","type":"fill","accept":["180"],"answer":"180","score":2,"hint":"获利 $20\\%$ 时售价 $=120\\times1.2=144$；设标价 $x$，$0.8x=144$，$x=180$。","why":"获利 $20\\%$ 时售价 $=120\\times1.2=144$；设标价 $x$，$0.8x=144$，$x=180$。"}],"solution":"获利 $20\\%$ 的售价 $=120\\times(1+20\\%)=144$ 元。\n设标价为 $x$，八折即 $0.8x$：\n$0.8x=144$\n$x=180$\n\n【验证】$180\\times0.8=144$，$(144-120)\\div120=20\\%$ ✓"},
  {"id":"cf-ch-38","chapter":"ch-rational","method":null,"tier":"l1","kind":"choice","score":2,"tierName":"选择 · 相反数与绝对值","errorTags":["calc"],"stem":"下列说法正确的是（　）","options":["$-5$ 的相反数是 $5$","$-5$ 的绝对值是 $-5$","$|-5|=-5$","$-(-5)=-5$"],"steps":[{"label":"计算","ask":"计算结果是？","type":"choice","options":["$-5$ 的相反数是 $5$","$-5$ 的绝对值是 $-5$","$|-5|=-5$","$-(-5)=-5$"],"key":0,"score":2,"hint":"$-5$ 的相反数是 $5$ ✓\n\n【逐项错因】\n· $|-5|=5$，不是 $-5$（绝对值非负）\n· $-(-5)=5$，不是 $-5$（负负得正）","why":"$-5$ 的相反数是 $5$ ✓\n\n【逐项错因】\n· $|-5|=5$，不是 $-5$（绝对值非负）\n· $-(-5)=5$，不是 $-5$（负负得正）"}]},
  {"id":"cf-fi-55","chapter":"ch-rational","method":null,"tier":"l1","kind":"fill","score":2,"tierName":"填空 · 绝对值","errorTags":["calc"],"stem":"若 $|x|=7$，则 $x=$ ___。","steps":[{"label":"计算","ask":"填写结果","type":"fill","accept":["7或-7","±7","-7或7"],"answer":"7或-7","score":2,"hint":"绝对值等于 7 的数有两个：$7$ 和 $-7$。","why":"绝对值等于 7 的数有两个：$7$ 和 $-7$。"}],"solution":"$|x|=7$，则 $x=7$ 或 $x=-7$。\n\n【要点】绝对值方程通常有两个解——数轴上到原点距离为 7 的点有两个。"},
  {"id":"cf-fi-56","chapter":"ch-rational","method":null,"tier":"l2","kind":"fill","score":2,"tierName":"填空 · 数轴距离","errorTags":["calc"],"stem":"数轴上点 $A$ 表示 $-4$，点 $B$ 表示 $6$，则 $AB=$ ___。","steps":[{"label":"计算","ask":"填写结果","type":"fill","accept":["10"],"answer":"10","score":2,"hint":"距离 $=|6-(-4)|=10$。","why":"距离 $=|6-(-4)|=10$。"}],"solution":"$AB=|6-(-4)|=|10|=10$。\n\n【要点】数轴上两点距离 $=|a-b|$，不是 $b-a$（不知大小关系时可能为负）。"},
  {"id":"cf-ch-40","chapter":"ch-op","method":"m-newdef","tier":"l2","kind":"choice","score":2,"tierName":"选择 · 进位制（十六进制）","errorTags":["concept"],"stem":"在网页设计中颜色常用十六进制编码。十六进制逢十六进一，用 $0\\sim9$ 和 $A\\sim F$ 表示 $0\\sim15$。换算方法：从右向左各数位分别乘 $16^{0},16^{1},16^{2},\\cdots$ 再相加。则十六进制数 $2A$ 表示的十进制数是（　）","options":["$42$","$22$","$210$","$26$"],"steps":[{"label":"按权展开","ask":"$2A$ 中 $A$ 表示 $10$。按权展开 $2\\times16^{1}+10\\times16^{0}=$？","type":"choice","options":["$42$","$22$","$210$","$26$"],"key":0,"score":2,"hint":"$2\\times16=32$，再加 $10$。","why":"$32+10=42$。"}],"solution":"$2A$：十位 $2$、个位 $A=10$。\n$2\\times16^{1}+10\\times16^{0}=32+10=42$。\n\n【易错】把 $2A$ 当成 $22$（以为 $A$ 就是 $1$）或 $210$（直接拼接）——十六进制的字母是 $10\\sim15$ 的数码。"},
  {"id":"cf-fi-57","chapter":"ch-op","method":"m-newdef","tier":"l2","kind":"fill","score":2,"tierName":"填空 · 进位制（算筹记数）","errorTags":["concept"],"stem":"算筹记数：个位用纵式、十位用横式、百位用纵式……从右到左纵横相间。已知某数从高位到低位依次是「百位 3、十位 4、个位 5」，则这个数是 ___。","steps":[{"label":"按位还原","ask":"百位 $3$、十位 $4$、个位 $5$，组成的数是？","type":"fill","accept":["345"],"answer":"345","score":2,"hint":"百位 ×100 + 十位 ×10 + 个位。","why":"$3\\times100+4\\times10+5=345$。"}],"solution":"百位 $3$、十位 $4$、个位 $5$：\n$3\\times100+4\\times10+5=345$。\n\n【要点】算筹与十进制同理——「位」决定权，纵横只是书写形式不同。真题 2025-26 第 15 题就是这个结构。"},
];